window.JBC_ATLAS_BC_EXPANSION=[{"name_en":"Abana","source_key":"ABANA","source_id":"k-ABANA","source_text":"Abana. Abana\nStony (Heb. marg. “Amanah,” perennial), the chief river of Damascus (2 Kings 5:12). Its modern name is Barada, the Chrysorrhoas, or “golden stream,” of the Greeks. It rises in a cleft of the Anti-Lebanon range, about 23 miles north-west of Damascus, and after flowing southward for a little way parts into three smaller streams, the central one flowing through Damascus, and the other two on each side of the city, diffusing beauty and fertility where otherwise there would be barrenness.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"4051b6935170b290a90d20e6478864804c28f1499e317c468c7c8461164675fb","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["2 Kings 5:12"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Abdon","source_key":"ABDON","source_id":"k-ABDON","source_text":"Abdon. Abdon\nServile. (1.) The son of Hillel, a Pirathonite, the tenth judge of Israel (Judg. 12:13-15). He is probably the Bedan of 1 Sam. 12:11.\n\n(2.) The first-born of Gibeon of the tribe of Benjamin (1 Chr. 8:30; 9:36).\n\n(3.) The son of Micah, one of those whom Josiah sent to the prophetess Huldah to ascertain from her the meaning of the recently discovered book of the law (2 Chr. 34:20). He is called Achbor in 2 Kings 22:12.\n\n(4.) One of the “sons” of Shashak (1 Chr. 8:23).\n\nThis is the name also of a Levitical town of the Gershonites, in the tribe of Asher (Josh. 21:30; 1 Chr. 6:74). The ruins of Abdeh, some 8 miles north-east of Accho, probably mark its site.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"f44d2ee99c33b9b2aa830d7b1bbf254585a5bec7724e321d123f39cc31b52731","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Judg. 12:13-15","1 Sam. 12:11","1 Chr. 8:30","2 Chr. 34:20","2 Kings 22:12","1 Chr. 8:23","Josh. 21:30","1 Chr. 6:74"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Abez","source_key":"ABEZ","source_id":"k-ABEZ","source_text":"Abez. Abez\nTin, or white, a town in the tribe of Issachar (Josh. 19:20), at the north of the plain of Esdraelon. It is probably identified with the ruins of el-Beida.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"아베스. 아베즈틴(Abez Tin) 또는 백색. 에스드라엘론 평원 북쪽에 있는 잇사갈 지파의 성읍(수 19:20). 그것은 아마도 엘베이다(el-Beida)의 폐허와 동일시될 것이다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"c430604390310b16186ecda728987be11784b52d7df7c0104266e9e72aaa4ec2","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:20"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Achzib","source_key":"ACHZIB","source_id":"k-ACHZIB","source_text":"Achzib. Achzib\nFalsehood. (1.) A town in the Shephelah, or plain country of Judah (Josh. 15:44); probably the same as Chezib of Gen. 38:5 = Ain Kezbeh.\n\n(2.) A Phoenician city (the Gr. Ecdippa), always retained in their possession though assigned to the tribe of Asher (Josh. 19:29; Judg. 1:31). It is identified with the modern es-Zib, on the Mediterranean, about 8 miles north of Accho.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"악십. 악십 거짓. (1) 셰펠라, 즉 유다 평야에 있는 성읍(수 15:44) 아마도 창세기 38:5 = 아인케스베의 크십과 동일할 것이다. (2) 페니키아의 도시(그리스 엑디파)는 아셀 지파에 할당되었음에도 불구하고 항상 그들의 소유로 유지되었다(수 19:29; 삿 1:31). 그것은 Acccho에서 북쪽으로 약 8마일 떨어진 지중해에 있는 현대의 es-Zib과 동일시됩니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"91cf21e3f915a2d6cc287d05617ea027799665f1ce5e53f4b969dbf40386926a","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:44","Gen. 38:5","Josh. 19:29","Judg. 1:31"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Adamah","source_key":"ADAMAH","source_id":"k-ADAMAH","source_text":"Adamah. Adamah\nRed earth, a fortified city of Naphtali, probably the modern Damieh, on the west side of the sea of Tiberias (Josh. 19:33, 36).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"5ef461cb2187e892640f4e8ad304822b80c534492188c6196cb23cf63fbbc7b3","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:33"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Adummim","source_key":"ADUMMIM","source_id":"k-ADUMMIM","source_text":"Adummim. Adummim\nThe red ones, a place apparently on the road between Jericho and Jerusalem, “on the south side of the torrent” Wady Kelt, looking toward Gilgal, mentioned Josh. 15:7; 18:17. It was nearly half-way between Jerusalem and Jericho, and now bears the name of Tal-at-ed-Dumm. It is supposed to have been the place referred to in the parable of the Good Samaritan (Luke 10:30-37). Recently a new carriage-road has been completed, and carriages for the first time have come along this road from Jerusalem.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"아둠밈. 아둠밈 붉은 물은 여리고와 예루살렘 사이의 길에 있는 것으로 보이는 장소로서 “급류 남쪽” 길갈을 바라보고 있는 와디켈트가 요쉬를 언급했습니다. 15:7; 18:17. 그 곳은 예루살렘과 여리고 사이의 거의 중간 지점에 있었으며 지금은 Tal-at-ed-Dumm이라는 이름을 갖고 있습니다. 선한 사마리아인의 비유(눅 10:30-37)에 나오는 곳으로 추정된다. 최근에 새로운 마차 길이 완성되었으며, 예루살렘에서 처음으로 마차가 이 길을 따라 왔습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"a71fcbd010483f44526be2fd76392e7d262df510cb4c2b68f7cdb3633da5ed95","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Josh. 15:7","Luke 10:30-37"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Ahava","source_key":"AHAVA","source_id":"k-AHAVA","source_text":"Ahava. Ahava\nWater, the river (Ezra 8:21) by the banks of which the Jewish exiles assembled under Ezra when about to return to Jerusalem from Babylon. In all probability this was one of the streams of Mesopotamia which flowed into the Euphrates somewhere in the north-west of Babylonia. It has, however, been supposed to be the name of a place (Ezra 8:15) now called Hit, on the Euphrates, east of Damascus.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":false},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"13b131b4c7410d1111d25d25f63a649084660c22fb661a30ad1a0c8af5465d69","source_evidence":{"geographic_types":["river","site"],"scripture_citations_as_printed":["Ezra 8:21","Ezra 8:15"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Akrabbim","source_key":"AKRABBIM","source_id":"k-AKRABBIM","source_text":"Akrabbim. Akrabbim\nScorpions, probably the general name given to the ridge containing the pass between the south of the Dead Sea and Zin, es-Sufah, by which there is an ascent to the level of the land of Palestine. Scorpions are said to abound in this whole district, and hence the name (Num. 34:4). It is called “Maaleh-acrabbim” in Josh. 15:3, and “the ascent of Akrabbim” in Num. 34:4.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"0486d721f1c7a3479e6b164c49f38c9dc14c6d7c5716265e191e399a3b7797ba","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Num. 34:4","Josh. 15:3","Num. 34:4"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Alemeth","source_key":"ALEMETH","source_id":"k-ALEMETH","source_text":"Alemeth. Alemeth\nCovering. (1.) One of the nine sons of Becher, the son of Benjamin (1 Chr. 7:8).\n\n(2.) One of the sons of Jehoadah, or Jarah, son of Ahaz (1 Chr. 8:36).\n\n(3.) A sacerdotal city of Benjamin (1 Chr. 6:60), called also Almon (Josh. 21:18), now Almit, a mile north-east of the ancient Anathoth.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"fccb25e6030857de5c060c3678ccc9b55f16caa4febdeb6ba7290adf11e3a85c","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["1 Chr. 7:8","1 Chr. 8:36","1 Chr. 6:60","Josh. 21:18"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Alexandria","source_key":"ALEXANDRIA","source_id":"k-ALEXANDRIA","source_text":"Alexandria. Alexandria\nThe ancient metropolis of Lower Egypt, so called from its founder, Alexander the Great (about B.C. 333). It was for a long period the greatest of existing cities, for both Nineveh and Babylon had been destroyed, and Rome had not yet risen to greatness. It was the residence of the kings of Egypt for 200 years. It is not mentioned in the Old Testament, and only incidentally in the New. Apollos, eloquent and mighty in the Scriptures, was a native of this city (Acts 18:24). Many Jews from Alexandria were in Jerusalem, where they had a synagogue (Acts 6:9), at the time of Stephen’s martyrdom. At one time it is said that as many as 10,000 Jews resided in this city. It possessed a famous library of 700,000 volumes, which was burned by the Saracens (A.D. 642). It was here that the Hebrew Bible was translated into Greek. This is called the Septuagint version, from the tradition that seventy learned men were engaged in executing it. It was, however, not all translated at one time. It was begun B.C. 280, and finished about B.C. 200 or 150. (See VERSION.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"1b5a81d3d739ca2ac9a1d068c25fb3135e7bce2546db260c1ad6dcf05aec90eb","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Acts 18:24","Acts 6:9"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Anab","source_key":"ANAB","source_id":"k-ANAB","source_text":"Anab. Anab\nGrape-town, one of the cities in the mountains of Judah, from which Joshua expelled the Anakim (Josh. 11:21; 15:50). It still retains its ancient name. It lies among the hills, 10 miles south-south-west of Hebron.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"1cafcb530bc902d57ab091471961de61f045ddb6e033da6131d91235edd856de","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 11:21"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Anim","source_key":"ANIM","source_id":"k-ANIM","source_text":"Anim. Anim\nFountains, a city in the mountains of Judah (Josh. 15:50), now el-Ghuwein, near Eshtemoh, about 10 miles south-west of Hebron.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"애니. 유다 산에 있는 도시(수 15:50)인 애니 분수(Anim Fountains)는 현재 헤브론에서 남서쪽으로 약 10마일 떨어진 에스테모 근처에 있는 엘 구와인입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"3a871a5164a76eea090c8ae49ef18ebd05baf7c14b935dc546f05b73178fb8ef","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:50"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Apollonia","source_key":"APOLLONIA","source_id":"k-APOLLONIA","source_text":"Apollonia. Apollonia\nA city of Macedonia between Amphipolis and Thessalonica, from which it was distant about 36 miles. Paul and Silas passed through it on their way to Thessalonica (Acts 17:1).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"아폴로니아. 아폴로니아 암피볼리와 데살로니가 사이에 있는 마케도니아의 도시로 약 36마일 떨어져 있습니다. 바울과 실라가 데살로니가로 가던 길에 이 곳을 지나갔습니다(행 17:1).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"12ba5d77e891b123e56e176e33c2b100f93032d99854a20b94ae52ed222921d0","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Acts 17:1"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Aram-naharaim","source_key":"ARAM-NAHARAIM","source_id":"k-ARAM-NAHARAIM","source_text":"Aram-naharaim. Aram-naharaim\nAram of the two rivers, is Mesopotamia (as it is rendered in Gen. 24:10), the country enclosed between the Tigris on the east and the Euphrates on the west (Ps. 60, title); called also the “field of Aram” (Hos. 12:12, R.V.) i.e., the open country of Aram; in the Authorized Version, “country of Syria.” Padan-aram (q.v.) was a portion of this country.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"0cb74d701b451d23f67ebee5a2df3ffa2d661369b21d34f0124f4771cd479dc9","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Gen. 24:10","Hos. 12:12"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Areopagus","source_key":"AREOPAGUS","source_id":"k-AREOPAGUS","source_text":"Areopagus. Areopagus\nThe Latin form of the Greek word rendered “Mars’ hill.” But it denotes also the council or court of justice which met in the open air on the hill. It was a rocky height to the west of the Acropolis at Athens, on the south-east summit of which the council was held which was constituted by Solon, and consisted of nine archons or chief magistrates who were then in office, and the ex-archons of blameless life.\n\nOn this hill of Mars (Gr. Ares) Paul delivered his memorable address to the “men of Athens” (Acts 17:22-31).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"f4b1c722c0192fc8110aee5cecfeaccff0accf1774c4cea4dc47dfc57269b4db","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Acts 17:22-31"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Argob","source_key":"ARGOB","source_id":"k-ARGOB","source_text":"Argob. Argob\nStony heap, an “island,” as it has been called, of rock about 30 miles by 20, rising 20 or 30 feet above the table-land of Bashan; a region of crags and chasms wild and rugged in the extreme. On this “island” stood sixty walled cities, ruled over by Og. It is called Trachonitis (“the rugged region”) in the New Testament (Luke 3:1). These cities were conquered by the Israelites (Deut. 3:4; 1 Kings 4:13). It is now called the Lejah. Here “sixty walled cities are still traceable in a space of 308 square miles. The architecture is ponderous and massive. Solid walls 4 feet thick, and stones on one another without cement; the roofs enormous slabs of basaltic rock, like iron; the doors and gates are of stone 18 inches thick, secured by ponderous bars. The land bears still the appearance of having been called the ‘land of giants’ under the giant Og.” “I have more than once entered a deserted city in the evening, taken possession of a comfortable house, and spent the night in peace. Many of the houses in the ancient cities of Bashan are perfect, as if only finished yesterday. The walls are sound, the roofs unbroken, and even the window-shutters in their places. These ancient cities of Bashan probably contain the very oldest specimens of domestic architecture in the world” (Porter’s Giant Cities). (See BASHAN.)","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"아르곱. 아르곱 돌무더기, 소위 “섬”으로, 가로 30마일, 세로 20마일 정도이고, 바산 고원보다 20~30피트 높이로 솟아 있습니다. 험준하고 깊은 틈이 있는 지역으로, 극도로 거칠고 울퉁불퉁합니다. 이 “섬”에는 옥이 통치하는 60개의 성벽 도시가 있었습니다. 신약성경에서는 이를 트라코니티스('험한 지역')라고 부릅니다(누가복음 3:1). 이 도시들은 이스라엘 사람들에 의해 정복되었습니다(신명기 3:4; 왕상 4:13). 지금은 레자(Lejah)라고 불립니다. 여기에는 \"60개의 성벽 도시가 308평방 마일의 공간에서 여전히 추적 가능합니다. 건축물은 육중하고 거대합니다. 4피트 두께의 단단한 벽과 시멘트 없이 서로 돌이 쌓여 있고, 지붕은 철과 같은 거대한 현무암 석판으로 되어 있으며, 문과 문은 두꺼운 막대로 고정된 18인치 두께의 돌입니다. 땅은 여전히 거인 옥의 밑에서 '거인의 땅'이라 불리던 모습.\" “나는 저녁에 한적한 도시에 들어간 적이 여러 번 있었고, 안락한 집을 소유하고 평화롭게 밤을 보냈습니다. 바산 고대 도시의 많은 집들은 마치 어제 완공된 것처럼 완벽합니다. 벽은 튼튼하고 지붕은 깨지지 않았으며 심지어 창문 덧문도 제자리에 있습니다. 바산의 이 고대 도시에는 아마도 세계에서 가장 오래된 국내 건축 표본이 있을 것입니다.”(포터의 거대 도시)(바산 참조)","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"2d9f7b443e2f9dee5ff780e339d12d793619e53fc387bb150616ba737a05e47c","source_evidence":{"geographic_types":["region"],"scripture_citations_as_printed":["Luke 3:1","Deut. 3:4","1 Kings 4:13"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Arpad","source_key":"ARPAD","source_id":"k-ARPAD","source_text":"Arpad. Arpad\n(Isa. 10:9; 36:19; 37:13), also Arphad, support, a Syrian city near Hamath, along with which it is invariably mentioned (2 Kings 19:13; 18:34; Isa. 10:9), and Damascus (Jer. 49:23). After a siege of three years it fell (B.C. 742) before the Assyrian king Tiglath-pileser II. Now Tell Erfud.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"8f69e8e2d50af72112dee634930780ef159e4a4526e3f00f070fc6f2037f921d","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Isa. 10:9","2 Kings 19:13","Isa. 10:9","Jer. 49:23"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Ashtaroth","source_key":"ASHTAROTH","source_id":"k-ASHTAROTH","source_text":"Ashtaroth. Ashtaroth\nA city of Bashan, in the kingdom of Og (Deut. 1:4; Josh. 12:4; 13:12; 9:10). It was in the half-tribe of Manasseh (Josh. 13:12), and as a Levitical city was given to the Gershonites (1 Chr. 6:71). Uzzia, one of David’s valiant men (1 Chr. 11:44), is named as of this city. It is identified with Tell Ashterah, in the Hauran, and is noticed on monuments B.C. 1700-1500. The name Beesh-terah (Josh. 21:27) is a contraction for Beth-eshterah, i.e., “the house of Ashtaroth.”","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"아스다롯. 아스다롯 옥의 왕국에 있는 바산의 성읍(신 1:4; 수 12:4; 13:12; 9:10). 그곳은 므낫세 반 지파에 있었고(수 13:12), 레위 지파의 성읍으로 게르손 자손에게 주어졌다(대상 6:71). 다윗의 용사 중 한 사람인 웃시야(대상 11:44)가 이 도시에서 이름을 따왔다. 그것은 하우란에 있는 텔 아스테라와 동일시되며 B.C. 기념물에도 나타난다. 1700-1500. 브에스데라(수 21:27)라는 이름은 벳에스드라, 즉 “아스다롯의 집”을 단축한 것입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"355775b1d7a287ab50f96f767d17652251edb3b031808f319da331bb12c71e7e","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Deut. 1:4","Josh. 12:4","Josh. 13:12","1 Chr. 6:71","1 Chr. 11:44","Josh. 21:27"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Ataroth","source_key":"ATAROTH","source_id":"k-ATAROTH","source_text":"Ataroth. Ataroth\nCrowns. (1.) A city east of Jordan, not far from Gilead (Num. 32:3).\n\n(2.) A town on the border of Ephraim and Benjamin (Josh. 16:2, 7), called also Ataroth-adar (16:5). Now ed-Da’rieh.\n\n(3.) “Ataroth, the house of Joab” (1 Chr. 2:54), a town of Judah inhabited by the descendants of Caleb.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"아타로스. 아타로스 크라운. (1) 길르앗에서 멀지 않은 요단 동쪽의 도시(민 32:3). (2) 에브라임과 베냐민의 경계에 있는 성읍(수 16:2, 7). 아다롯아달이라고도 불린다(16:5). 이제 ed-Da'rieh입니다. (3.) “요압의 집 아다롯”(대상 2:54), 갈렙 자손이 거주하는 유다의 성읍.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"c223cb7d843849291be25db029887a1b7e51d6533f04a4264bb993f66e6a9076","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Num. 32:3","Josh. 16:2","1 Chr. 2:54"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Azmaveth","source_key":"AZMAVETH","source_id":"k-AZMAVETH","source_text":"Azmaveth. Azmaveth\nStrong as death. (1.) One of David’s thirty warriors (2 Sam. 23:31).\n\n(2.) An overseer over the royal treasury in the time of David and Solomon (1 Chr. 27:25).\n\n(3.) A town in the tribe of Judah, near Jerusalem (Neh. 12:29; Ezra 2:24).\n\n(4.) 1 Chr. 8:36","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"아스마베스. 아즈마베스는 죽음만큼 강합니다. (1.) 다윗의 30용사 중 한 사람(삼하 23:31). (2) 다윗과 솔로몬 시대의 왕실 보고를 맡은 감독자(대상 27:25). (3) 예루살렘 근처 유다 지파의 성읍(느 12:29; 스 2:24). (4.) 1 Chr. 8:36","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"0b3b3b5db41781dcf2be40d254dddd8ebb580fd968b8a3d85a1035fb02cdc908","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["2 Sam. 23:31","1 Chr. 27:25","Neh. 12:29","Ezra 2:24","1 Chr. 8:36"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Baalah","source_key":"BAALAH","source_id":"k-BAALAH","source_text":"Baalah. Baalah\nMistress; city. (1.) A city in the south of Judah (Josh. 15:29), elsewhere called Balah (Josh. 19:3) and Bilhah (1 Chr. 4:29). Now Khurbet Zebalah.\n\n(2.) A city on the northern border of the tribe of Judah (Josh. 15:10), called also Kirjath-jearim, q.v. (15:9; 1 Chr. 13:6), now Kuriet-el-Enab, or as some think, ‘Erma.\n\n(3.) A mountain on the north-western boundary of Judah and Dan (Josh. 15:11).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"바알라. 바알라 여주인; 도시. (1) 유다 남쪽에 있는 도시(수 15:29). 다른 곳에서는 발라(수 19:3)와 빌하(대상 4:29)라고도 불린다. 이제 Khurbet Zebalah입니다. (2) 기럇여아림이라고도 불리는 유다 지파의 북쪽 경계에 있는 도시(수 15:10) (15:9; 대상 13:6), 이제는 Kuriet-el-Enab 또는 일부 사람들이 생각하는 것처럼 'Erma. (3) 유다와 단의 북서쪽 경계에 있는 산(수 15:11).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"49d6a78b5be699ef15b0b8023a36ab85fbea27034d8ba7d57b56300078aac59f","source_evidence":{"geographic_types":["settlement","mountain"],"scripture_citations_as_printed":["Josh. 15:29","Josh. 19:3","1 Chr. 4:29","Josh. 15:10","1 Chr. 13:6","Josh. 15:11"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Baalath","source_key":"BAALATH","source_id":"k-BAALATH","source_text":"Baalath. Baalath\nA town of the tribe of Dan (Josh. 19:44). It was fortified by Solomon (1 Kings 9:18; 2 Chr. 8:6). Some have identified it with Bel’ain, in Wady Deir Balut.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"바알랏. 바알랏 단 지파의 성읍(수 19:44). 이 성은 솔로몬에 의해 요새화되었습니다(왕상 9:18; 대하 8:6). 일부는 그것을 Wady Deir Balut의 Bel'ain과 동일시했습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"0d872a324efecc960c136e6652e2aaf5416b64097d214574755b0c47d8f06dbe","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:44","1 Kings 9:18","2 Chr. 8:6"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Baalath-beer","source_key":"BAALATH-BEER","source_id":"k-BAALATH-BEER","source_text":"Baalath-beer. Baalath-beer\nBaalah of the well, (Josh. 19:8, probably the same as Baal, mentioned in 1 Chr. 4:33, a city of Simeon.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"바알랏 맥주. 바알랏-브엘 우물의 바알라(수 19:8, 아마도 대상 4:33에 언급된 시므온의 성 바알과 동일함).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"663bda44da3c316756598b489ee2b2900b79799192c51510499e6cf2dc7ea459","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:8","1 Chr. 4:33"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Baal-hazor","source_key":"BAAL-HAZOR","source_id":"k-BAAL-HAZOR","source_text":"Baal-hazor. Baal-hazor\nHaving a courtyard, or Baal’s village, the place on the borders of Ephraim and Benjamin where Absalom held the feast of sheep-shearing when Amnon was assassinated (2 Sam. 13:23). Probably it is the same with Hazor (Neh. 11:33), now Tell’ Asur, 5 miles north-east of Bethel.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"2d7a03ecbb7e4397f784ab4ec9b8c949c1a087bd9200fd2f48db754afb056de7","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["2 Sam. 13:23","Neh. 11:33"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Baal-hermon","source_key":"BAAL-HERMON","source_id":"k-BAAL-HERMON","source_text":"Baal-hermon. Baal-hermon\nLord of Hermon. (1.) A city near Mount Hermon inhabited by the Ephraimites (1 Chr. 5:23). Probably identical with Baal-gad (Josh. 11:17).\n\n(2.) A mountain east of Lebanon (Judg. 3:3). Probably it may be the same as Mount Hermon, or one of its three peaks.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"바알헤르몬. 바알-헤르몬 헤르몬의 주인. (1) 에브라임 사람들이 거주했던 헤르몬 산 근처의 도시(대상 5:23). 아마도 바알갓(수 11:17)과 동일할 것이다. (2.) 레바논 동쪽의 산(삿 3:3). 아마도 그것은 헤르몬 산이나 그 세 봉우리 중 하나와 같을 것이다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"b6bfa6d3eb256e383984dbe112f4a267e949e763ba3d08c9e79974ee32d177bb","source_evidence":{"geographic_types":["settlement","mountain"],"scripture_citations_as_printed":["1 Chr. 5:23","Josh. 11:17","Judg. 3:3"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Baal-meon","source_key":"BAAL-MEON","source_id":"k-BAAL-MEON","source_text":"Baal-meon. Baal-meon\nLord of dwelling, a town of Reuben (Num. 32:38), called also Beth-meon (Jer. 48:23) and Beth-baal-meon (Josh. 13:17). It is supposed to have been the birth-place of Elisha. It is identified with the modern M’ain, about 3 miles south-east of Heshbon.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"바알멘. 거주하시는 주 바알므온. 르우벤 성읍(민 32:38). 벳므온(렘 48:23) 및 벳바알므온(수 13:17)이라고도 불림. 엘리사가 태어난 곳으로 추정된다. 이곳은 헤스본에서 남동쪽으로 약 3마일 떨어진 현대의 마인과 동일시됩니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"256f6df2054e438be3cc9bd29c3c903b7e2ebe1bda2d4cb27511534ff6489ace","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Num. 32:38","Jer. 48:23","Josh. 13:17"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Baal-perazim","source_key":"BAAL-PERAZIM","source_id":"k-BAAL-PERAZIM","source_text":"Baal-perazim. Baal-perazim\nBaal having rents, bursts, or destructions, the scene of a victory gained by David over the Philistines (2 Sam. 5:20; 1 Chr. 14:11). Called Mount Perazim (Isa. 28:21). It was near the valley of Rephaim, west of Jerusalem. Identified with the modern Jebel Aly.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"c852d2859efdd58164dd6bbbe68f1bddddb7ee3cc63cd9aa3551b177333180b5","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["2 Sam. 5:20","1 Chr. 14:11","Isa. 28:21"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Baal-tamar","source_key":"BAAL-TAMAR","source_id":"k-BAAL-TAMAR","source_text":"Baal-tamar. Baal-tamar\nLord of palm trees, a place in the tribe of Benjamin near Gibeah of Saul (Judg. 20:33). It was one of the sanctuaries or groves of Baal. Probably the palm tree of Deborah (Judg. 4:5) is alluded to in the name.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"바알다말. 바알다말은 사울의 기브아 근처 베냐민 지파의 한 곳인 종려나무의 주인이다(삿 20:33). 그곳은 바알의 성소나 숲 중 하나였습니다. 아마도 드보라의 종려나무(삿 4:5)가 그 이름에 암시되어 있을 것이다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"cf2e85fc0ee4572bab6aa3d0ea073639b0d90890b72a8ecb1c802666a92c21ad","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Judg. 20:33","Judg. 4:5"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Baal-zephon","source_key":"BAAL-ZEPHON","source_id":"k-BAAL-ZEPHON","source_text":"Baal-zephon. Baal-zephon\nBaal of the north, an Egyptian town on the shores of the Gulf of Suez (Ex. 14:2; Num. 33:7), over against which the children of Israel encamped before they crossed the Red Sea. It is probably to be identified with the modern Jebel Deraj or Kulalah, on the western shore of the Gulf of Suez. Baal-zapuna of the Egyptians was a place of worship.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"바알스본. 북쪽의 바알-스폰 바알. 수에즈 만 기슭에 있는 이집트의 도시(출 14:2; 민 33:7). 이스라엘 자손이 홍해를 건너기 전에 그 곳에 진을 쳤다. 아마도 수에즈 만 서쪽 해안에 있는 현대의 Jebel Deraj 또는 Kulalah와 동일시될 것입니다. 이집트인들의 바알자푸나는 예배의 장소였습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"8ac0c7f67304f9b0248ad866ba311d2ce8641432f630f0502d836de5da261b07","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Ex. 14:2","Num. 33:7"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Beth-arabah","source_key":"BETH-ARABAH","source_id":"k-BETH-ARABAH","source_text":"Beth-arabah. Beth-arabah\nHouse of the desert, one of the six cities of Judah, situated in the sunk valley of the Jordan and Dead Sea (Josh. 18:22). In Josh. 15:61 it is said to have been “in the wilderness.” It was afterwards included in the towns of Benjamin. It is called Arabah (Josh. 18:18).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"f4f52f225e82acce2f95c397e114fe470d36cd2903c50770b93d4e6975f9e2af","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 18:22","Josh. 15:61","Josh. 18:18"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Beth-aven","source_key":"BETH-AVEN","source_id":"k-BETH-AVEN","source_text":"Beth-aven. Beth-aven\nHouse of nothingness; i.e., “of idols”, a place in the mountains of Benjamin, east of Bethel (Josh. 7:2; 18:12; 1 Sam. 13:5). In Hos. 4:15; 5:8; 10:5 it stands for “Bethel” (q.v.), and it is so called because it was no longer the “house of God,” but “the house of idols,” referring to the calves there worshipped.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"벳아웬. 벳아웬 무의 집; 즉, “우상의”, 벧엘 동쪽 베냐민 산에 있는 장소(수 7:2; 18:12; 삼상 13:5). 호스에서. 4:15; 5:8; 10:5 그것은 “벧엘”(q.v.)을 의미하며 더 이상 “하나님의 집”이 아니고 “우상의 집”이 되었기 때문에 그렇게 불린다. 그곳에서 예배하는 송아지를 가리킨다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"33f615da5c8e9955b59eae0b250d9239f130ab0cc87de6a179c93a873cd0c878","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Josh. 7:2","1 Sam. 13:5","Hos. 4:15"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Beth-barah","source_key":"BETH-BARAH","source_id":"k-BETH-BARAH","source_text":"Beth-barah. Beth-barah\nHouse of crossing, a place south of the scene of Gideon’s victory (Judg. 7:24). It was probably the chief ford of the Jordan in that district, and may have been that by which Jacob crossed when he returned from Mesopotamia, near the Jabbok (Gen. 32:22), and at which Jephthah slew the Ephraimites (Judg. 12:4). Nothing, however, is certainly known of it. (See BETHABARA.)","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"벳바라. 벳바라 건너편의 집, 기드온이 승리한 곳 남쪽에 있는 곳(삿 7:24). 그것은 아마도 그 지역에 있는 요르단 강의 주요 나루였을 것이며, 야곱이 메소포타미아에서 돌아올 때 얍복 근처에서 건너던 곳이었을 것이며(창 32:22), 입다가 그곳에서 에브라임 사람들을 죽였을 것이다(삿 12:4). 그러나 이에 대해 확실히 알려진 바는 없습니다. (베타바라 참조)","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"2e7f8ce633b4687f06981d7982309c3aa9c8b565e58735d138c72dd334e933b8","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Judg. 7:24","Gen. 32:22","Judg. 12:4"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Beth-dagon","source_key":"BETH-DAGON","source_id":"k-BETH-DAGON","source_text":"Beth-dagon. Beth-dagon\nHouse of Dagon. (1.) A city in the low country or plain of Judah, near Philistia (Josh. 15:41); the modern Beit Degan, about 5 miles from Lydda.\n\n(2.) A city near the south-east border of Asher (Josh. 19:27). It was a Philistine colony. It is identical with the modern ruined village of Tell D’auk.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"벳다곤. 벳다곤 다곤의 집. (1) 블레셋 근처 저지대나 유다 평야에 있는 도시(수 15:41) Lydda에서 약 5마일 떨어진 현대적인 Beit Degan. (2) 아셀의 남동쪽 경계 근처에 있는 도시(수 19:27). 그곳은 블레셋 식민지였습니다. 현대의 폐허 마을인 텔도크(Tell D'auk)와 동일합니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"d75ffc76b582c1b194642f389bc4648fede810600341baa2d07b6dca2f707505","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:41","Josh. 19:27"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Beth-haccerem","source_key":"BETH-HACCEREM","source_id":"k-BETH-HACCEREM","source_text":"Beth-haccerem. Beth-haccerem\nHouse of a vineyard, a place in the tribe of Judah (Neh. 3:14) where the Benjamites were to set up a beacon when they heard the trumpet against the invading army of the Babylonians (Jer. 6:1). It is probable that this place is the modern ‘Ain Karim, or “well of the vineyards,” near which there is a ridge on which are cairns which may have served as beacons of old, one of which is 40 feet high and 130 in diameter.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"벳학게렘. 벳학게렘 포도원의 집, 유다 지파의 한 장소(느 3:14) 베냐민 사람들이 바벨론의 침략군을 향하여 나팔 소리를 들었을 때 봉화대를 세웠던 곳(렘 6:1). 이 장소는 아마도 현대의 '아인 카림(Ain Karim) 또는 \"포도원의 우물\"일 가능성이 높습니다. 그 근처에는 고대의 봉화 역할을 했을 돌무더기가 있는 능선이 있는데, 그 중 하나는 높이가 40피트이고 직경이 130입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"49f77432ab791e3bf4f0d623666594a6f56ea93e5e5f507f006483aee85318b7","source_evidence":{"geographic_types":["mountain","site"],"scripture_citations_as_printed":["Neh. 3:14","Jer. 6:1"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Beth-peor","source_key":"BETH-PEOR","source_id":"k-BETH-PEOR","source_text":"Beth-peor. Beth-peor\nHouse of Peor; i.e., “temple of Baal-peor”, a place in Moab, on the east of Jordan, opposite Jericho. It was in the tribe of Reuben (Josh. 13:20; Deut. 3:29; 4:46). In the “ravine” or valley over against Beth-peor Moses was probably buried (Deut. 34:6).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"벳브올. 벳브올 프올의 집; 즉, 여리고 맞은편 요단 동편 모압에 있는 “바알브올 신전”이다. 그것은 르우벤 지파에 속했다(수 13:20; 신 3:29; 4:46). 모세는 아마도 벳브올 맞은편의 “골짜기” 또는 골짜기에 묻혔을 것입니다(신 34:6).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"60b75fffe0ce3f89127c6ad83d35b65333105f6d5cd2940143d444ac2571c705","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Josh. 13:20","Deut. 3:29","Deut. 34:6"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Beth-tappuah","source_key":"BETH-TAPPUAH","source_id":"k-BETH-TAPPUAH","source_text":"Beth-tappuah. Beth-tappuah\nHouse of apples, a town of Judah, now Tuffuh, 5 miles west of Hebron (Josh. 15:53).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"벳답부아. 벳답부아 사과의 집, 헤브론에서 서쪽으로 5마일 떨어진 유다 성읍(현재 투푸)(수 15:53).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"305e43a0035a773db178b84b602d86f624111e92f39927272aa109ef39859e24","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:53"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Besor","source_key":"BESOR","source_id":"k-BESOR","source_text":"Besor. Besor\nCold, a ravine or brook in the extreme south-west of Judah, where 200 of David’s men stayed behind because they were faint, while the other 400 pursued the Amalekites (1 Sam. 30:9, 10, 21). Probably the Wadyes Sheriah, south of Gaza.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"0ed412faeb992414667133092a3a83c5cd7b3ecb846c4632c73cd4353e05fece","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["1 Sam. 30:9"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Bezer","source_key":"BEZER","source_id":"k-BEZER","source_text":"Bezer. Bezer\nOre of gold or silver. (1.) A city of the Reubenites; one of the three cities of refuge on the east of Jordan (Deut. 4: 43; Josh. 20:8). It has been identified with the modern ruined village of Burazin, some 12 miles north of Heshbon; also with Kasur-el-Besheir, 2 miles south-west of Dibon.\n\n(2.) A descendant of Asher (1 Chr. 7:37).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"베셀. 금이나 은의 베셀 광석. (1) 르우벤 지파의 도시. 요단 동편에 있는 세 도피성 중 하나(신명기 4:43; 수 20:8). 이곳은 헤스본에서 북쪽으로 약 12마일 떨어진 현대의 폐허가 된 마을인 부라진(Burazin)과 동일시됩니다. 또한 Dibon에서 남서쪽으로 3.2km 떨어진 Kasur-el-Besheir도 있습니다. (2) 아셀의 후손(대상 7:37).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"4956fd93ebd813eb38a7a93f95e5dac67fe20d611d43115586045a64b636c491","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Deut. 4: 43","Josh. 20:8","1 Chr. 7:37"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Bithron","source_key":"BITH-RON","source_id":"k-BITH-RON","source_text":"Bith-ron. Bith-ron\nThe broken or divided place, a district in the Arabah or Jordan valley, on the east of the river (2 Sam. 2:29). It was probably the designation of the region in general, which is broken and intersected by ravines.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"비트론. 비트론 강 동쪽 아라바 또는 요단 계곡에 있는 부서지거나 나누어진 지역(삼하 2:29). 그것은 아마도 계곡이 부서지고 교차하는 일반적인 지역의 지정이었을 것입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"11449cfecdbb455d0a2517c1a7a145674fb75951f84a723a783efc5f57ab7366","source_evidence":{"geographic_types":["river","region"],"scripture_citations_as_printed":["2 Sam. 2:29"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Bosor","source_key":"BOSOR","source_id":"k-BOSOR","source_text":"Bosor. Bosor\nThe Chaldee or Aramaic form of the name Beor, the father of Balaam (2 Pet. 2:15).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":false},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"7a27e6cd2eaefde00325bb18149d0e44458e062e9f12ee87dee7837a7cac9284","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":[],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Cabul","source_key":"CABUL","source_id":"k-CABUL","source_text":"Cabul. Cabul\nHow little! as nothing. (1.) A town on the eastern border of Asher (Josh. 19:27), probably one of the towns given by Solomon to Hiram; the modern Kabul, some 8 miles east of Accho, on the very borders of Galilee.\n\n(2.) A district in the north-west of Galilee, near to Tyre, containing twenty cities given to Hiram by Solomon as a reward for various services rendered to him in building the temple (1 Kings 9:13), and as payment of the six score talents of gold he had borrowed from him. Hiram gave the cities this name because he was not pleased with the gift, the name signifying “good for nothing.” Hiram seems afterwards to have restored these cities to Solomon (2 Chr. 8:2).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"카불. 카불 얼마나 적은가! 아무것도 아닌 것처럼. (1) 아셀 동쪽 경계에 있는 성읍(수 19:27). 아마도 솔로몬이 히람에게 준 성읍 중 하나였을 것이다. 현재의 카불은 Acccho에서 동쪽으로 약 8마일 떨어진 갈릴리 경계에 있습니다. (2) 두로 근처 갈릴리 북서쪽에 있는 한 지역. 솔로몬이 성전을 건축할 때 그에게 바친 여러 가지 봉사에 대한 보상으로(왕상 9:13), 그리고 솔로몬이 그에게서 빌린 금 육십 달란트를 지불하기 위해 히람에게 준 20개의 성읍이 포함되어 있다. 히람은 그 예물을 기뻐하지 않았기 때문에 그 도시들에 이 이름을 붙였는데, 그 이름은 “아무것도 아닌”이라는 뜻이었습니다. 후에 히람은 이 성읍들을 솔로몬에게 회복시킨 것으로 보인다(대하 8:2).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"8f37685d23105878f0be0ff1f84587f9f28d7a8de355088c49ae148ad4df122a","source_evidence":{"geographic_types":["settlement","region"],"scripture_citations_as_printed":["Josh. 19:27","1 Kings 9:13","2 Chr. 8:2"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Calah","source_key":"CALAH","source_id":"k-CALAH","source_text":"Calah. Calah\nOne of the most ancient cities of Assyria. “Out of that land he [i.e., Nimrod] went forth into Assyria, and built Nineveh, Rehoboth-Ir, and Calah, and Resen” (Gen. 10:11, R.V.). Its site is now marked probably by the Nimrud ruins on the left bank of the Tigris. These cover an area of about 1,000 acres, and are second only in size and importance to the mass of ruins opposite Mosul. This city was at one time the capital of the empire, and was the residence of Sardanapalus and his successors down to the time of Sargon, who built a new capital, the modern Khorsabad. It has been conjectured that these four cities mentioned in Gen. 10:11 were afterwards all united into one and called Nineveh (q.v.).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"00eabfd4e6cc7688b0a99b52aa7fbcb016669a67649dc52cb0e2911a4ec92b6b","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Gen. 10:11","Gen. 10:11"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Calneh","source_key":"CALNEH","source_id":"k-CALNEH","source_text":"Calneh. Calneh\nFort, one of the four cities founded by Nimrod (Gen. 10:10). It is the modern Niffer, a lofty mound of earth and rubbish situated in the marshes on the left, i.e., the east, bank of the Euphrates, but 30 miles distant from its present course, and about 60 miles south-south-east from Babylon. It is mentioned as one of the towns with which Tyre carried on trade. It was finally taken and probably destroyed by one of the Assyrian kings (Amos 6:2). It is called Calno (Isa. 10:9) and Canneh (Ezek. 27:23).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"5959a531f37052486b961c9bfe2d793ce84ca3711b8eee0605382d6d92e8e9c7","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Gen. 10:10","Amos 6:2","Isa. 10:9","Ezek. 27:23"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Cana","source_key":"CANA","source_id":"k-CANA","source_text":"Cana. Cana\nReedy, a town of Galilee, near Capernaum. Here our Lord wrought his first miracle, the turning of water into wine (John 2:1-11; 4:46). It is also mentioned as the birth-place of Nathanael (21:2). It is not mentioned in the Old Testament. It has been identified with the modern Kana el-Jelil, also called Khurbet Kana, a place 8 or 9 miles north of Nazareth. Others have identified it with Kefr Kenna, which lies on the direct road to the Sea of Galilee, about 5 miles north-east of Nazareth, and 12 in a direct course from Tiberias. It is called “Cana of Galilee,” to distinguish it from Cana of Asher (Josh. 19:28).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"카나. 가버나움 근처 갈릴리 마을 가나리디. 여기서 우리 주님은 물을 포도주로 바꾸는 첫 번째 기적을 행하셨습니다(요한복음 2:1-11; 4:46). 이곳은 나다나엘의 출생지로도 언급된다(21:2). 구약성서에는 언급되어 있지 않습니다. 이곳은 나사렛에서 북쪽으로 8~9마일 떨어진 곳인 Khurbet Kana라고도 불리는 현대의 Kana el-Jelil과 동일시됩니다. 다른 사람들은 그것을 나사렛에서 북동쪽으로 약 5마일 떨어진 갈릴리 바다로 향하는 직통 도로에 있는 케프 케나(Kefr Kenna)와 티베리아스에서 직행 경로에 있는 12개라고 밝혔습니다. 아셀 가나와 구별하여 “갈릴리 가나”라고 부릅니다(수 19:28).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"b37fc6133f1e3545fc6bb843466cb5272c05cc30e89249f779b7580c68c30c92","source_evidence":{"geographic_types":["settlement","site"],"scripture_citations_as_printed":["John 2:1-11","Josh. 19:28"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Caphtor","source_key":"CAPHTOR","source_id":"k-CAPHTOR","source_text":"Caphtor. Caphtor\nA chaplet, the original seat of the Philistines (Deut. 2:23; Jer. 47:4; Amos 9:7). The name is found written in hieroglyphics in the temple of Kom Ombos in Upper Egypt. But the exact situation of Caphtor is unknown, though it is supposed to be Crete, since the Philistines seem to be meant by the “Cherethites” in 1 Sam. 30:14 (see also 2 Sam. 8:18). It may, however, have been a part of Egypt, the Caphtur in the north Delta, since the Caphtorim were of the same race as the Mizraite people (Gen. 10:14; 1 Chr. 1:12).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"a47a242d6840a9b481d68da27f044429fc712e89c68f8008fb5dd4a9cb478f4d","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Deut. 2:23","Jer. 47:4","Amos 9:7","1 Sam. 30:14","2 Sam. 8:18","Gen. 10:14","1 Chr. 1:12"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Cenchrea","source_key":"CENCHREA","source_id":"k-CENCHREA","source_text":"Cenchrea. Cenchrea\nMillet, the eastern harbour of Corinth, from which it was distant about 9 miles east, and the outlet for its trade with the Asiatic shores of the Mediterranean. When Paul returned from his second missionary journey to Syria, he sailed from this port (Acts 18:18). In Rom. 16:1 he speaks as if there were at the time of his writing that epistle an organized church there. The western harbour of Corinth was Lechaeum, about a mile and a half from the city. It was the channel of its trade with Italy and the west.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"7e17d8c8efabf363f1b31f7426f2139557f2828c80d29844177f8be1172cd514","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Acts 18:18","Rom. 16:1"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Cherith","source_key":"CHERITH","source_id":"k-CHERITH","source_text":"Cherith. Cherith\nA cutting; separation; a gorge, a torrent-bed or winter-stream, a “brook,” in whose banks the prophet Elijah hid himself during the early part of the three years’ drought (1 Kings 17:3, 5). It has by some been identified as the Wady el-Kelt behind Jericho, which is formed by the junction of many streams flowing from the mountains west of Jericho. It is dry in summer. Travellers have described it as one of the wildest ravines of this wild region, and peculiarly fitted to afford a secure asylum to the persecuted. But if the prophet’s interview with Ahab was in Samaria, and he thence journeyed toward the east, it is probable that he crossed Jordan and found refuge in some of the ravines of Gilead. The “brook” is said to have been “before Jordan,” which probably means that it opened toward that river, into which it flowed. This description would apply to the east as well as to the west of Jordan. Thus Elijah’s hiding-place may have been the Jermuk, in the territory of the half-tribe of Manasseh.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"2c69d302e15f5c7d0362f260a3f2abca7b4bffd8f599fce5edff39ae18a30e6e","source_evidence":{"geographic_types":["river"],"scripture_citations_as_printed":["1 Kings 17:3"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Chinnereth","source_key":"CHINNERETH","source_id":"k-CHINNERETH","source_text":"Chinnereth. Chinnereth\nLyre, the singular form of the word (Deut. 3:17; Josh. 19:35), which is also used in the plural form, Chinneroth, the name of a fenced city which stood near the shore of the lake of Galilee, a little to the south of Tiberias. The town seems to have given its name to a district, as appears from 1 Kings 15:20, where the plural form of the word is used.\n\nThe Sea of Chinnereth (Num. 34:11; Josh. 13:27), or of Chinneroth (Josh. 12: 3), was the “lake of Gennesaret” or “sea of Tiberias” (Deut. 3:17; Josh. 11:2). Chinnereth was probably an ancient Canaanitish name adopted by the Israelites into their language.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"긴네렛. 긴네렛 리라(Chinnereth Lyre), 단수형(신 3:17; 수 19:35). 이 단어는 복수형으로도 사용된다. 긴네롯은 디베랴에서 조금 남쪽에 있는 갈릴리 호수 기슭 근처에 서 있던 울타리가 있는 도시의 이름이다. 이 도시는 단어의 복수형이 사용된 열왕기상 15:20에 나오는 것처럼 지역에 그 이름을 붙인 것 같습니다. 긴네렛 바다(민 34:11; 수 13:27) 또는 긴네롯 바다(수 12:3)는 “게네사렛 호수” 또는 “디베랴 바다”(신 3:17; 수 11:2)였습니다. 긴네렛은 아마도 이스라엘 사람들이 그들의 언어로 채택한 고대 가나안 이름이었을 것입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"5ce4b44860dcf98f2277f738300699ec2602a2878b1e324aabf1d888797c45a6","source_evidence":{"geographic_types":["region"],"scripture_citations_as_printed":["Deut. 3:17","Josh. 19:35","1 Kings 15:20","Num. 34:11","Josh. 13:27","Josh. 12: 3","Deut. 3:17","Josh. 11:2"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Chios","source_key":"CHIOS","source_id":"k-CHIOS","source_text":"Chios. Chios\nMentioned in Acts 20:15, an island in the Aegean Sea, about 5 miles distant from the mainland, having a roadstead, in the shelter of which Paul and his companions anchored for a night when on his third missionary return journey. It is now called Scio.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"치오스. 사도행전 20:15에 언급된 키오스(Chios)는 본토에서 약 5마일 떨어진 에게해에 있는 섬으로, 길가가 있었고, 바울과 그의 동료들이 세 번째 선교 여행에서 귀환할 때 그곳에서 하룻밤을 묵었습니다. 이제는 Scio라고 불립니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"62394eef85113c8d1f295dedc80875221ba5194d9782b3e3ca618a049d45fdc0","source_evidence":{"geographic_types":["region"],"scripture_citations_as_printed":["Acts 20:15"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Colossae","source_key":"COLOSSAE","source_id":"k-COLOSSAE","source_text":"Colossae. Colossae\nOr Colosse, a city of Phrygia, on the Lycus, which is a tributary of the Maeander. It was about 12 miles above Laodicea, and near the great road from Ephesus to the Euphrates, and was consequently of some mercantile importance. It does not appear that Paul had visited this city when he wrote his letter to the church there (Col. 1:2). He expresses in his letter to Philemon (ver. 1:22) his hope to visit it on being delivered from his imprisonment. From Col. 1:7; 4:12 it has been concluded that Epaphras was the founder of the Colossian church. This town afterwards fell into decay, and the modern town of Chonas or Chonum occupies a site near its ruins.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":false},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"c448e71107ffa03f7ee0f634cb21513d188ec77d4df4b9428838ed1b29a058d2","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":[],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Coos","source_key":"COOS","source_id":"k-COOS","source_text":"Coos. Coos\n(written Cos in the R.V.), a small island, one of the Sporades in the Aegean Sea, in the north-west of Rhodes, off the coast of Caria. Paul on his return from his third missionary journey, passed the night here after sailing from Miletus (Acts 21:1). It is now called Stanchio.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"ff9303eac8340fdc9deb453e2a782353fce88ee7e29bb060bcd74694c6a8e89d","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Acts 21:1"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Debir","source_key":"DEBIR","source_id":"k-DEBIR","source_text":"Debir. Debir\nOracle town; sanctuary. (1.) One of the eleven cities to the west of Hebron, in the highlands of Judah (Josh. 15:49; Judg. 1:11-15). It was originally one of the towns of the Anakim (Josh. 15:15), and was also called Kirjath-sepher (q.v.) and Kirjath-sannah (49). Caleb, who had conquered and taken possession of the town and district of Hebron (Josh. 14:6-15), offered the hand of his daughter to any one who would successfully lead a party against Debir. Othniel, his younger brother (Judg. 1:13; 3:9), achieved the conquest, and gained Achsah as his wife. She was not satisfied with the portion her father gave her, and as she was proceeding toward her new home, she “lighted from off her ass” and said to him, “Give me a blessing [i.e., a dowry]: for thou hast given me a south land” (Josh. 15:19, A.V.); or, as in the Revised Version, “Thou hast set me in the land of the south”, i.e., in the Negeb, outside the rich valley of Hebron, in the dry and barren land. “Give me also springs of water. And he gave her the upper springs, and the nether springs.”\n\nDebir has been identified with the modern Edh-Dhaheriyeh, i.e., “the well on the ridge”, to the south of Hebron.\n\n(2.) A place near the “valley of Achor” (Josh. 15:7), on the north boundary of Judah, between Jerusalem and Jericho.\n\n(3.) The king of Eglon, one of the five Canaanitish kings who were hanged by Joshua (Josh. 10:3, 23) after the victory at Gibeon. These kings fled and took refuge in a cave at Makkedah. Here they were kept confined till Joshua returned from the pursuit of their discomfited armies, when he caused them to be brought forth, and “Joshua smote them, and slew them, and hanged them on five trees” (26).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"96f9ef022c84f1b40ae4c6a89df120cbf287aa0d4927674cc9b5cf4c77aaa06d","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 15:49","Judg. 1:11-15","Josh. 15:15","Josh. 14:6-15","Judg. 1:13","Josh. 15:19","Josh. 15:7","Josh. 10:3"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Dibon","source_key":"DIBON","source_id":"k-DIBON","source_text":"Dibon. Dibon\nPining; wasting. (1.) A city in Moab (Num. 21:30); called also Dibon-gad (33:45), because it was built by Gad and Dimon (Isa. 15:9). It has been identified with the modern Diban, about 3 miles north of the Arnon and 12 miles east of the Dead Sea. (See Moabite Stone.)\n\n(2.) A city of the tribe of Judah, inhabited after the Captivity (Neh. 11:25); called also Dimonah (Josh. 15:22). It is probably the modern ed-Dheib.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"디본. 디본 피닝; 낭비. (1) 모압의 한 도시(민 21:30); 갓과 디몬이 건축하였기 때문에 디본갓이라고도 불린다(33:45).(사 15:9) 이곳은 아르논에서 북쪽으로 약 3마일, 사해에서 동쪽으로 12마일 떨어진 현대의 디반과 동일시된다. (모압 돌 참조) (2) 유다 지파의 도시. 포로 생활 이후에 사람이 거주함(느 11:25). 디모나라고도 불린다(수 15:22). 아마도 현대의 ed-Dheib 일 것입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"47d2c12b851fb67a7d3783dcc133621502e392949493564a34301dfe1a2c1608","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Num. 21:30","Isa. 15:9","Neh. 11:25","Josh. 15:22"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Dizahab","source_key":"DIZAHAB","source_id":"k-DIZAHAB","source_text":"Dizahab. Dizahab\nRegion of gold, a place in the desert of Sinai, on the western shore of the Elanitic gulf (Deut. 1:1). It is now called Dehab.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"디자합. 디사합 황금 지역, 엘라니 만 서쪽 해안에 있는 시내 광야에 있는 곳(신 1:1). 지금은 데합(Dehab)이라고 불립니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"02be7666d10973f3960a1b43f3f5ae9bc0e77db041d57d6663dd037799c1503b","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Deut. 1:1"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Dumah","source_key":"DUMAH","source_id":"k-DUMAH","source_text":"Dumah. Dumah\nSilence, (comp. Ps. 94:17), the fourth son of Ishmael; also the tribe descended from him; and hence also the region in Arabia which they inhabited (Gen. 25:14; 1 Chr. 1:30).\n\nThere was also a town of this name in Judah (Josh. 15:52), which has been identified with ed-Domeh, about 10 miles southwest of Hebron. The place mentioned in the “burden” of the prophet Isaiah (21:11) is Edom or Idumea.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"두마. 이스마엘의 넷째 아들인 두마 침묵(시 94:17을 비교하라). 또한 그 지파도 그의 후손이었다. 따라서 그들이 거주했던 아라비아 지역도 그러했다(창 25:14; 대상 1:30). 유다에도 이 이름의 성읍이 있었는데(수 15:52) 헤브론에서 남서쪽으로 약 10마일 떨어진 에드돔과 동일시된다. 이사야 선지자의 “짐”(21:11)에 언급된 장소는 에돔 또는 이두메입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"013adc1cf3ba2084e14e5b46ea3c737b5e9d2d0303fc423c70c7c793ea83b56d","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Ps. 94:17","Gen. 25:14","1 Chr. 1:30","Josh. 15:52"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Elealeh","source_key":"ELEALEH","source_id":"k-ELEALEH","source_text":"Elealeh. Elealeh\nGod has ascended, a place in the pastoral country east of Jordan, in the tribe of Reuben (Num. 32:3, 37). It is not again mentioned till the time of Isaiah (15:4; 16:9) and Jeremiah (48:34). It is now an extensive ruin called el-A’al, about one mile north-east of Heshbon.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"엘레알레. 엘르알레 하나님은 요단 동편 목축지 르우벤 지파의 한 곳으로 올라가셨습니다(민 32:3, 37). 이사야(15:4; 16:9)와 ​​예레미야(48:34) 시대까지는 이 이름이 다시 언급되지 않았습니다. 지금은 헤스본에서 북동쪽으로 약 1마일 떨어진 엘아알이라는 광대한 폐허가 되었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"9f0d8936415a0cb56a825e795da95cb56e8a65825891587d773191c34905d12c","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Num. 32:3"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Elim","source_key":"ELIM","source_id":"k-ELIM","source_text":"Elim. Elim\nTrees, (Ex. 15:27; Num. 33:9), the name of the second station where the Israelites encamped after crossing the Red Sea. It had “twelve wells of water and threescore and ten palm trees.” It has been identified with the Wady Ghurundel, the most noted of the four wadies which descend from the range of et-Tih towards the sea. Here they probably remained some considerable time. The form of expression in Ex. 16:1 seems to imply that the people proceeded in detachments or companies from Elim, and only for the first time were assembled as a complete host when they reached the wilderness of Sin (q.v.).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"ccd5bd841d17e086bcd3d734aa6d881e582b121b0c9e711098556377fc69220e","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Ex. 15:27","Num. 33:9","Ex. 16:1"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Elon","source_key":"ELON","source_id":"k-ELON","source_text":"Elon. Elon\nOak. (1.) A city of Dan (Josh. 19:43). (2.) A Hittite, father of Bashemath, Esau’s wife (Gen. 26:34). (3.) One of the sons of Zebulun (Gen. 46:14). (4.) The eleventh of the Hebrew judges. He held office for ten years (Judg. 12:11, 12). He is called the Zebulonite.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"엘론. 엘론 오크. (1) 단의 성(수 19:43). (2) 에서의 아내 바스맛의 아버지인 헷 사람(창 26:34). (3) 스불론의 아들 중 한 사람(창 46:14). (4.) 히브리인 사사 중 열한번째. 그는 10년 동안 재직했습니다(삿 12:11, 12). 그는 스불론 사람이라고 불립니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"cf23ba40e75b6033339dc753e149575f0790f2c22ba068858ca81fb0814b1b3d","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:43","Gen. 26:34","Gen. 46:14","Judg. 12:11"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"En-eglaim","source_key":"EN-EGLAIM","source_id":"k-EN-EGLAIM","source_text":"En-eglaim. En-eglaim\nFountain of two calves, a place mentioned only in Ezek. 47:10. Somewhere near the Dead Sea.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"엔에글라임. 엔-에글라임 두 송아지의 샘, 에스겔에만 언급된 장소. 47:10. 사해 근처 어딘가.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"00fcf5fb74241f824185b5e91288ab3d2cd3ffb2b981cb2846cec83bc83dd153","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Ezek. 47:10"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"En-gannim","source_key":"EN-GANNIM","source_id":"k-EN-GANNIM","source_text":"En-gannim. En-gannim\nFountain of gardens. (1.) A town in the plains of Judah (Josh. 15:34), north-west of Jerusalem, between Zanoah and Tappuah. It is the modern Umm Jina.\n\n(2.) A city on the border of Machar (Josh. 19:21), allotted to the Gershonite Levites (21:29). It is identified with the modern Jenin, a large and prosperous town of about 4,000 inhabitants, situated 15 miles south of Mount Tabor, through which the road from Jezreel to Samaria and Jerusalem passes. When Ahaziah, king of Judah, attempted to escape from Jehu, he “fled by the way of the garden house” i.e., by way of En-gannim. Here he was overtaken by Jehu and wounded in his chariot, and turned aside and fled to Megiddo, a distance of about 20 miles, to die there.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"엔간님. 엔간님 정원의 분수. (1) 사노아와 답부아 사이, 예루살렘 북서쪽 유다 평야에 있는 성읍(수 15:34). 현대의 엄지나 입니다. (2) 마갈 경계에 있는 성읍(수 19:21), 게르손 사람 레위 사람들에게 할당됨(21:29). 이 도시는 이스르엘에서 사마리아와 예루살렘으로 가는 도로가 통과하는 다볼 산에서 남쪽으로 15마일 떨어진 곳에 위치한 약 4,000명의 주민이 살고 있는 크고 번영하는 도시인 현대의 예닌과 동일시됩니다. 유다 왕 아하시야는 예후를 피해 도망치려고 했을 때 “동산 집 길”, 즉 엔간님 길로 도망했습니다. 여기서 그는 예후에게 붙잡혀 병거를 타고 부상을 입었고, 방향을 틀어 약 20마일 떨어진 므깃도로 도망하여 그곳에서 죽었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"be88dc38422c1cb593a9aa0ea955bd6a872e5e2d63a7985aadcd2c6e8477ae3e","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:34","Josh. 19:21"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"En-hakkore","source_key":"EN-HAKKORE","source_id":"k-EN-HAKKORE","source_text":"En-hakkore. En-hakkore\nFountain of the crier, the name of the spring in Lehi which burst forth in answer to Samson’s prayer when he was exhausted with the slaughter of the Philistines (Judg. 15:19). It has been identified with the spring ‘Ayun Kara, near Zoreah.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"a755f27921bf056dc55fdb8b3a0bda678115eb608afe4383b3e3ee6a01418d65","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Judg. 15:19"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"En-shemesh","source_key":"EN-SHEMESH","source_id":"k-EN-SHEMESH","source_text":"En-shemesh. En-shemesh\nFountain of the sun a spring which formed one of the landmarks on the boundary between Judah and Benjamin (Josh. 15:7; 18:17). It was between the “ascent of Adummim” and the spring of En-rogel, and hence was on the east of Jerusalem and of the Mount of Olives. It is the modern ‘Ain-Haud i.e., the “well of the apostles” about a mile east of Bethany, the only spring on the road to Jericho. The sun shines on it the whole day long.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"c5ed4a8f775466119fb7ce71bf1ee05604672c35261fdcdf50d9a168b320c048","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Josh. 15:7"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Ephratah","source_key":"EPHRATAH","source_id":"k-EPHRATAH","source_text":"Ephratah. Ephratah\nFruitful. (1.) The second wife of Caleb, the son of Hezron, mother of Hur, and grandmother of Caleb, who was one of those that were sent to spy the land (1 Chr. 2:19, 50).\n\n(2.) The ancient name of Bethlehem in Judah (Gen. 35:16, 19; 48:7). In Ruth 1:2 it is called “Bethlehem-Judah,” but the inhabitants are called “Ephrathites;” in Micah 5:2, “Bethlehem-Ephratah;” in Matt. 2:6, “Bethlehem in the land of Judah.” In Ps. 132:6 it is mentioned as the place where David spent his youth, and where he heard much of the ark, although he never saw it till he found it long afterwards at Kirjath-jearim; i.e., the “city of the wood,” or the “forest-town” (1 Sam. 7:1; comp. 2 Sam. 6:3, 4).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"48f5bdf41d710e512f42b75db7bc03af14cb65f8195740824f84e670c6303853","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["1 Chr. 2:19","Gen. 35:16","Matt. 2:6","Ps. 132:6","1 Sam. 7:1","2 Sam. 6:3"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Ephron","source_key":"EPHRON","source_id":"k-EPHRON","source_text":"Ephron. Ephron\nFawn-like. (1.) The son of Zohar a Hittite, the owner of the field and cave of Machpelah (q.v.), which Abraham bought for 400 shekels of silver (Gen. 23:8-17; 25:9; 49:29, 30).\n\n(2.) A mountain range which formed one of the landmarks on the north boundary of the tribe of Judah (Josh. 15:9), probably the range on the west side of the Wady Beit-Hanina.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"에프론. 에프론 폰 같은. (1.) 아브라함이 은 400세겔에 구입한 막벨라(q.v.) 밭과 굴의 소유자인 헷 족속 소하르의 아들(창 23:8-17; 25:9; 49:29, 30). (2.) 유다 지파의 북쪽 경계에 있는 랜드마크 중 하나를 형성한 산맥(수 15:9), 아마도 Wady Beit-Hanina의 서쪽에 있는 산맥이었을 것이다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"4fd2e26fb3816b4e5ea5b92f114a0147587893b56ef6ab0e42466db4a65520b8","source_evidence":{"geographic_types":["mountain"],"scripture_citations_as_printed":["Gen. 23:8-17","Josh. 15:9"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Etham","source_key":"ETHAM","source_id":"k-ETHAM","source_text":"Etham. Etham\nPerhaps another name for Khetam, or “fortress,” on the Shur or great wall of Egypt, which extended from the Mediterranean to the Gulf of Suez. Here the Israelites made their third encampment (Ex. 13:20; Num. 33:6). The camp was probably a little to the west of the modern town of Ismailia. Here the Israelites were commanded to change their route (Ex. 14:2), and “turn” towards the south, and encamp before Pi-hahiroth. (See EXODUS; PITHOM.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"e50657964a50b52c3031a02f449fe6f7c945087d0d8c072c13bd687194156e9b","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Ex. 13:20","Num. 33:6","Ex. 14:2"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Ezer","source_key":"EZER","source_id":"k-EZER","source_text":"Ezer. Ezer\nTreasure. (1.) One of the sons of Seir, the native princes, “dukes,” of Mount Hor (Gen. 36:21, 27). (2.) 1 Chr. 7:21; (3.) 4:4. (4.) One of the Gadite champions who repaired to David at Ziklag (12:9). (5.) A Levite (Neh. 3:19). (6.) A priest (12:42).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"cbe3b29cf91c7dc8b556672d70aff78fb5188aa41e4de6a4ed5b365332b6f34f","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Gen. 36:21","1 Chr. 7:21","Neh. 3:19"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Gabbatha","source_key":"GABBATHA","source_id":"k-GABBATHA","source_text":"Gabbatha. Gabbatha\nGab Baitha, i.e., “the ridge of the house” = “the temple-mound,” on a part of which the fortress of Antonia was built. This “temple-mound” was covered with a tesselated “pavement” (Gr. lithostroton, i.e., “stone-paved”). A judgement-seat (bema) was placed on this “pavement” outside the hall of the “praetorium” (q.v.), the judgment-hall (John 18:28; 19:13).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"a67b486b4d73478a30e8e8b2bfcac508a8602ce964aa7585fde0e8d3705ec378","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["John 18:28"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Geder","source_key":"GEDER","source_id":"k-GEDER","source_text":"Geder. Geder\nA walled place, (Josh. 12:13), perhaps the same as Gederah or Gedor (15:58).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"b13c12a623149053b0289b3a35f7fde8a90dc0a5b389208fb0a704e9dfefdda2","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 12:13"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Gederah","source_key":"GEDERAH","source_id":"k-GEDERAH","source_text":"Gederah. Gederah\nThe fortress; a fortified place, a town in the plain (shephelah) of Judah (Josh. 15:36). This is a very common Canaanite and Phoenician name. It is the feminine form of Geder (12:13); the plural form is Gederoth (15:41). This place has by some been identified with Jedireh, a ruin 9 miles from Lydda, toward Eleutheropolis, and 4 miles north of Sur’ah (Zorah), in the valley of Elah.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"게데라. 게데라 요새; 요새화된 곳, 유다 평야(셰펠라)에 있는 성읍(수 15:36). 이것은 매우 일반적인 가나안 및 페니키아 이름입니다. 게델의 여성형이다(12:13). 복수형은 그데롯이다(15:41). 일부 사람들은 이곳이 뤼다에서 엘류테로폴리스 방향으로 9마일 떨어져 있고 수라(소라)에서 북쪽으로 4마일 떨어진 엘라 계곡에 있는 폐허인 여디레와 동일시합니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"3f690e4dc2513cb7289d78b8d2ea20c7a285e4adc2779bc519ec5b51f9e1de27","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:36"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Gerizim","source_key":"GERIZIM","source_id":"k-GERIZIM","source_text":"Gerizim. Gerizim\nA mountain of Samaria, about 3,000 feet above the Mediterranean. It was on the left of the valley containing the ancient town of Shechem (q.v.), on the way to Jerusalem. It stood over against Mount Ebal, the summits of these mountains being distant from each other about 2 miles (Deut. 27; Josh. 8:30-35). On the slopes of this mountain the tribes descended from the handmaids of Leah and Rachel, together with the tribe of Reuben, were gathered together, and gave the responses to the blessing pronounced as the reward of obedience, when Joshua in the valley below read the whole law in the hearing of all the people; as those gathered on Ebal responded with a loud Amen to the rehearsal of the curses pronounced on the disobedient. It was probably at this time that the coffin containing the embalmed body of Joseph was laid in the “parcel of ground which Jacob bought of the sons of Hamor” (Gen. 33:19; 50:25).\n\nJosephus relates (Ant. 11:8, 2-4) that Sanballat built a temple for the Samaritans on this mountain, and instituted a priesthood, as rivals to those of the Jews at Jerusalem. This temple was destroyed after it had stood two hundred years. It was afterwards rebuilt by Herod the Great. There is a Samaritan tradition that it was the scene of the incident recorded in Gen. 22. There are many ruins on this mountain, some of which are evidently of Christian buildings. To this mountain the woman of Sychar referred in John 4:20. For centuries Gerizim was the centre of political outbreaks. The Samaritans (q.v.), a small but united body, still linger here, and keep up their ancient ceremonial worship.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"그리심. 그리심(Gerizim) 지중해에서 약 3,000피트 높이에 있는 사마리아 산. 그것은 예루살렘으로 가는 길에 고대 세겜 성읍(q.v.)이 있는 계곡의 왼편에 있었습니다. 그것은 에발 산을 바라보고 서 있었고, 이 산들의 정상들은 서로 약 2 마일 떨어져 있었습니다(신명기 27장; 수 8:30-35). 이 산 기슭에 레아와 라헬의 후손 지파들과 르우벤 지파가 함께 모여 순종의 상으로 선포되는 축복에 화답하였더니, 아래 골짜기에서 여호수아가 모든 백성에게 율법을 낭독하니라. 에발에 모인 사람들이 불순종한 자들에게 선포된 저주에 대해 큰 소리로 아멘으로 응답했던 것과 같습니다. 아마도 관이 이때였을 것이다. 방부 처리된 요셉의 시신이 담긴 것은 “야곱이 하몰의 자손들에게서 산 한 밭”에 놓여졌습니다(창 33:19; 50:25). 요세푸스는 산발랏이 이 ​​산에 사마리아인들을 위한 성전을 건축하고 예루살렘에 있는 유대인의 제사장들과 경쟁할 수 있는 제사장직을 제정했다고 설명합니다(안 11:8, 2-4). 이 성전은 세워진 지 200년 만에 파괴되었습니다. 그 후 헤롯 대왕이 재건했습니다. 사마리아 전승에 따르면 이곳이 창세기 22장에 기록된 사건의 현장이었다. 이 산에는 유적이 많이 있는데, 그 중 일부는 기독교 건물인 것으로 보인다. 수가의 여인은 요한복음 4장 20절에서 이 산을 언급했습니다. 수세기 동안 그리심은 정치적 발발의 중심지였습니다. 작지만 연합된 단체인 사마리아인(q.v.)은 여전히 ​​여기에 머물며 계속해서 뒤따르고 있습니다. 그들의 고대 의식 예배.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"3263ee73a52a2a90327af0dd4848b4dbf177b0374d2e4cf808ed7fea62ffdcb0","source_evidence":{"geographic_types":["mountain"],"scripture_citations_as_printed":["Josh. 8:30-35","Gen. 33:19","John 4:20"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Gethsemane","source_key":"GETHSEMANE","source_id":"k-GETHSEMANE","source_text":"Gethsemane. Gethsemane\nOil-press, the name of an olive-yard at the foot of the Mount of Olives, to which Jesus was wont to retire (Luke 22:39) with his disciples, and which is specially memorable as being the scene of his agony (Mark 14:32; John 18:1; Luke 22:44). The plot of ground pointed out as Gethsemane is now surrounded by a wall, and is laid out as a modern European flower-garden. It contains eight venerable olive-trees, the age of which cannot, however, be determined. The exact site of Gethsemane is still in question. Dr. Thomson (The Land and the Book) says: “When I first came to Jerusalem, and for many years afterward, this plot of ground was open to all whenever they chose to come and meditate beneath its very old olivetrees. The Latins, however, have within the last few years succeeded in gaining sole possession, and have built a high wall around it...The Greeks have invented another site a little to the north of it...My own impression is that both are wrong. The position is too near the city, and so close to what must have always been the great thoroughfare eastward, that our Lord would scarcely have selected it for retirement on that dangerous and dismal night...I am inclined to place the garden in the secluded vale several hundred yards to the north-east of the present Gethsemane.”","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"d7a29b2df0395a0b87efd1a50938a71f8181b9c55e8e4547f63c23d34005d643","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Luke 22:39","Mark 14:32","John 18:1","Luke 22:44"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Gimzo","source_key":"GIMZO","source_id":"k-GIMZO","source_text":"Gimzo. Gimzo\nA place fertile in sycamores, a city in the plain of Judah, the villages of which were seized by the Philistines (2 Chr. 28:18). It is now called Jimzu, about 3 miles south-east of Ludd, i.e., Lydda.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"김조. 김조 뽕나무가 많은 비옥한 곳으로 유다 평지에 있는 성읍이요 그 마을들은 블레셋 사람들에게 점령되었느니라(대하 28:18). 지금은 Ludd, 즉 Lydda에서 남동쪽으로 약 3마일 떨어진 Jimzu라고 불립니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"6acf5b5c6af08a1f8cd45d4898713f00dabe8e85f2c1cea2fdcd56b4dd00d174","source_evidence":{"geographic_types":["settlement","site"],"scripture_citations_as_printed":["2 Chr. 28:18"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Gittaim","source_key":"GITTAIM","source_id":"k-GITTAIM","source_text":"Gittaim. Gittaim\nTwo wine-presses, (2 Sam. 4:3; Neh. 11:33), a town probably in Benjamin to which the Beerothites fled.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"Gittaim. 깃다임 두 개의 포도주 틀,(삼하 4:3; 느 11:33) 브에롯 사람들이 도망한 베냐민에 있는 성읍으로 추정됨.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"0904dab46682b5c84d611f669fb1bbf3f0047d844b0460fc0575f8b1dae728f3","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["2 Sam. 4:3","Neh. 11:33"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Hadad-rimmon","source_key":"HADAD-RIMMON","source_id":"k-HADAD-RIMMON","source_text":"Hadad-rimmon. Hadad-rimmon\n(composed of the names of two Syrian idols), the name of a place in the valley of Megiddo. It is alluded to by the prophet Zechariah (12:11) in a proverbial expression derived from the lamentation for Josiah, who was mortally wounded near this place (2 Chr. 35:22-25). It has been identified with the modern Rummaneh, a village “at the foot of the Megiddo hills, in a notch or valley about an hour and a half south of Tell Metzellim.”","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"하다드림몬. 하닷림몬(두 명의 시리아 우상의 이름으로 구성됨), 므깃도 골짜기에 있는 한 장소의 이름. 이는 스가랴 선지자(12:11)가 이 곳 근처에서 치명상을 입은 요시야를 애도한 것(대하 35:22~25)에서 파생된 속담 표현에서 암시된 것이다. 이 마을은 “텔 메트첼림에서 남쪽으로 약 한 시간 반 거리에 있는 골짜기 또는 골짜기에 있는 므깃도 언덕 기슭”의 마을인 현대의 루마네와 동일시됩니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"7339f8935a725371462f0c3ec7c15de97cd905bd0a985a12ccf5848b7003361f","source_evidence":{"geographic_types":["settlement","site"],"scripture_citations_as_printed":["2 Chr. 35:22-25"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Halah","source_key":"HALAH","source_id":"k-HALAH","source_text":"Halah. Halah\nA district of Media to which captive Israelites were transported by the Assyrian kings (2 Kings 17:6; 18:11; 1 Chr. 5:26). It lay along the banks of the upper Khabur, from its source to its junction with the Jerujer. Probably the district called by Ptolemy Chalcitis.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"ㅋㅋㅋ 할라 포로 이스라엘 사람들이 앗수르 왕들에 의해 이송된 메디아 지역(왕하 17:6; 18:11; 대상 5:26). 그것은 수원지로부터 예루제르(Jerujer)와의 교차점까지 상류 카부르(Khabur) 강둑을 따라 놓여 있었다. 아마도 프톨레마이오스 칼키티스가 불렀던 지역일 것입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"a67258a1e038d149ae9f8265554052041e5ba7c00debd98e63006926dd24b35e","source_evidence":{"geographic_types":["region"],"scripture_citations_as_printed":["2 Kings 17:6","1 Chr. 5:26"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Hammath","source_key":"HAMMATH","source_id":"k-HAMMATH","source_text":"Hammath. Hammath\nWarm springs, one of the “fenced cities” of Naphtali (Josh. 19:35). It is identified with the warm baths (the heat of the water ranging from 136 degrees to 144 degrees) still found on the shore a little to the south of Tiberias under the name of Hummam Tabariyeh (“Bath of Tiberias”).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"e7f74ae071fddb6b5016df7c0b1695b55cf3ecd9e89de27aca5df80393fc3504","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 19:35"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Hammoth-dor","source_key":"HAMMOTH-DOR","source_id":"k-HAMMOTH-DOR","source_text":"Hammoth-dor. Hammoth-dor\nWarm springs, a Levitical city of Naphtali (Josh. 21:32); probably Hammath in 19:35.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"94b6542e2850d8ab83c1ef2d412d3e431653a56951ed851a04774812bf6f6a4d","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 21:32"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Hamonah","source_key":"HAMONAH","source_id":"k-HAMONAH","source_text":"Hamonah. Hamonah\nMultitude, a name figuratively assigned to the place in which the slaughter and burial of the forces of Gog were to take place (Ezek. 39:16).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"957579702914e4349edda26e4c8de795178c7d57c4711f5c42e3e4f9d4340c13","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Ezek. 39:16"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Hareth","source_key":"HARETH","source_id":"k-HARETH","source_text":"Hareth. Hareth\nThicket, a wood in the mountains of Judah where David hid when pursued by Saul (1 Sam. 22:5). It was possibly while he was here that the memorable incident narrated in 2 Sam. 23:14-17, 1 Chr. 11:16-19 occurred. This place has not been identified, but perhaps it may be the modern Kharas, on the borders of the chain of mountains some 3 miles east of Keilah.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"d09ef8bfa206ca7fd1d9da1b39f1fed54c31c1a8ea09a6481e49e0f24e7bf714","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["1 Sam. 22:5","2 Sam. 23:14-17","1 Chr. 11:16-19"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Hazar-addar","source_key":"HAZAR-ADDAR","source_id":"k-HAZAR-ADDAR","source_text":"Hazar-addar. Hazar-addar\nVillage of Addar, a place in the southern boundary of Palestine (Num. 34:4), in the desert to the west of Kadesh-barnea. It is called Adar in Josh. 15:3.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"하자르-아달. 하살아달 마을은 팔레스타인 남쪽 경계에 있는 곳이며(민 34:4) 가데스바네아 서쪽 광야에 있다. 조쉬에서는 Adar라고 합니다. 15:3.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"e2e10044891c7368584178b4bfac78deec5a5471ff4ca693e176c3cd2081baa9","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Num. 34:4","Josh. 15:3"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Hazar-enan","source_key":"HAZAR-ENAN","source_id":"k-HAZAR-ENAN","source_text":"Hazar-enan. Hazar-enan\nVillage of fountains, a place on the north-east frontier of Palestine (Num. 34:9, 10). Some have identified it with Ayan ed-Dara in the heart of the central chain of Anti-Libanus. More probably, however, it has been identified with Kuryetein, about 60 miles east-north-east of Damascus. (Comp. Ezek. 47:17; 48:1.)","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"하자르에난. 하살에난 분수 마을, 팔레스타인 북동쪽 변경에 있는 곳(민 34:9, 10). 일부에서는 이를 Anti-Libanus의 중앙 체인 중심부에 있는 Ayan ed-Dara와 동일시했습니다. 그러나 아마도 다마스쿠스에서 동북동쪽으로 약 60마일 떨어진 쿠리에테인(Kuryetein)으로 확인되었을 가능성이 더 높습니다. (겔 47:17; 48:1을 비교하라.)","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"8a92aac2c2667980730d754ef96f7e8a0eee2fa901096411aeb8f0d4f72840e8","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Num. 34:9","Ezek. 47:17"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Hazar-shual","source_key":"HAZAR-SHUAL","source_id":"k-HAZAR-SHUAL","source_text":"Hazar-shual. Hazar-shual\nVillage or enclosure of the jackal, a city on the south border of Judah (Josh. 15:28; Neh. 11:27). It has been identified with the ruins of Saweh, half-way between Beersheba and Moladah.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"하살수알. 하살수알 마을 또는 유다 남쪽 국경에 있는 도시인 자칼의 성벽(수 15:28; 느 11:27). 그것은 브엘세바와 몰라다의 중간 지점에 있는 사웨(Saweh)의 폐허와 동일시되었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"36c2f0e477ba2f1c34000f49c9a53a7f978e8987d25113919766fb19daba9fbe","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:28","Neh. 11:27"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Helbah","source_key":"HELBAH","source_id":"k-HELBAH","source_text":"Helbah. Helbah\nFatness, a town of the tribe of Asher (Judg. 1:31), in the plain of Phoenicia.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"헬바. 페니키아 평야에 있는 아셀 지파의 성읍 헬바 비넷(삿 1:31).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"554499d8b300f5d582429b72288e0a82baf9a2ee1a869307fa4624e9155cf953","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Judg. 1:31"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Helkath","source_key":"HELKATH","source_id":"k-HELKATH","source_text":"Helkath. Helkath\nSmoothness, a town of Asher, on the east border (Josh. 19:25; 21:31); called also Hukok (1 Chr. 6:75).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"헬카스. 동쪽 경계에 있는 아셀 성읍 헬갓 스무네스(수 19:25; 21:31); 후곡이라고도 불린다(대상 6:75).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"635df81788ce55b4b6a7402321e192333a777af1e89020869ac221cf888b1ad0","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:25","1 Chr. 6:75"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Helkath-hazzurim","source_key":"HELKATH-HAZZURIM","source_id":"k-HELKATH-HAZZURIM","source_text":"Helkath-hazzurim. Helkath-hazzurim\nPlot of the sharp blades, or the field of heroes, (2 Sam. 2:16). After the battle of Gilboa, so fatal to Saul and his house, David, as divinely directed, took up his residence in Hebron, and was there anointed king over Judah. Among the fugitives from Gilboa was Ish-bosheth, the only surviving son of Saul, whom Abner, Saul’s uncle, took across the Jordan to Mahanaim, and there had him proclaimed king. Abner gathered all the forces at his command and marched to Gibeon, with the object of wresting Judah from David. Joab had the command of David’s army of trained men, who encamped on the south of the pool, which was on the east of the hill on which the town of Gibeon was built, while Abner’s army lay on the north of the pool. Abner proposed that the conflict should be decided by twelve young men engaging in personal combat on either side. So fiercely did they encounter each other that “they caught every man his fellow by the head, and thrust his sword in his fellow’s side; so they fell down together: wherefore that place was called Helkath-hazzurim.” The combat of the champions was thus indecisive, and there followed a severe general engagement between the two armies, ending in the total rout of the Israelites under Abner. The general result of this battle was that “David waxed stronger and stronger, and the house of Saul waxed weaker and weaker” (2 Sam. 3:1). (See GIBEON.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"4eade2935a76d9dc8bf48264c6489a4126d15cf15b161ae39a8fbfcfb79189ef","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["2 Sam. 2:16","2 Sam. 3:1"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Hen","source_key":"HEN","source_id":"k-HEN","source_text":"Hen. Hen\nCommon in later times among the Jews in Palestine (Matt. 23:37; Luke 13:34). It is noticeable that this familiar bird is only mentioned in these passages in connection with our Lord’s lamentation over the impenitence of Jerusalem.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"048df869c5aa36c20d9aa283e242dadc6906c6c3188f19c816a3287659e01104","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Matt. 23:37","Luke 13:34"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Hepher","source_key":"HEPHER","source_id":"k-HEPHER","source_text":"Hepher. Hepher\nA well or stream. (1.) A royal city of the Canaanites taken by Joshua (12:17).\n\n(2.) The youngest son of Gilead (Num. 26:32; 27:1).\n\n(3.) The second son of Asher (1 Chr. 4:6).\n\n(4.) One of David’s heroes (1 Chr. 11:36).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"e7e2766c5c03a98be485d26293c981b6b7d06ee9d0db9d9ed09bf8ecf117d04f","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Num. 26:32","1 Chr. 4:6","1 Chr. 11:36"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Hermon","source_key":"HERMON","source_id":"k-HERMON","source_text":"Hermon. Hermon\nA peak, the eastern prolongation of the Anti-Lebanon range, reaching to the height of about 9,200 feet above the Mediterranean. It marks the north boundary of Palestine (Deut. 3:8, 4:48; Josh. 11:3, 17; 13:11; 12:1), and is seen from a great distance. It is about 40 miles north of the Sea of Galilee. It is called “the Hermonites” (Ps. 42:6) because it has more than one summit. The Sidonians called it Sirion, and the Amorites Shenir (Deut. 3:9; Cant. 4:8). It is also called Baal-hermon (Judg. 3:3; 1 Chr. 5:23) and Sion (Deut. 4:48). There is every probability that one of its three summits was the scene of the transfiguration (q.v.). The “dew of Hermon” is referred to (Ps. 89: 12). Its modern name is Jebel-esh-Sheikh, “the chief mountain.” It is one of the most conspicuous mountains in Palestine or Syria. “In whatever part of Palestine the Israelite turned his eye northward, Hermon was there, terminating the view. From the plain along the coast, from the Jordan valley, from the heights of Moab and Gilead, from the plateau of Bashan, the pale, blue, snow-capped cone forms the one feature in the northern horizon.”\n\nOur Lord and his disciples climbed this “high mountain apart” one day, and remained on its summit all night, “weary after their long and toilsome ascent.” During the night “he was transfigured before them; and his face did shine as the sun.” The next day they descended to Caesarea Philippi.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"17533072a479854ca5c3059fbca9ed8213f947dea5d02a65552ba20e09dfa33e","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Deut. 3:8","Josh. 11:3","Ps. 42:6","Deut. 3:9","Judg. 3:3","1 Chr. 5:23","Deut. 4:48","Ps. 89: 12"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Hinnom","source_key":"HINNOM","source_id":"k-HINNOM","source_text":"Hinnom. Hinnom\nA deep, narrow ravine separating Mount Zion from the so-called “Hill of Evil Counsel.” It took its name from “some ancient hero, the son of Hinnom.” It is first mentioned in Josh. 15:8. It had been the place where the idolatrous Jews burned their children alive to Moloch and Baal. A particular part of the valley was called Tophet, or the “fire-stove,” where the children were burned. After the Exile, in order to show their abhorrence of the locality, the Jews made this valley the receptacle of the offal of the city, for the destruction of which a fire was, as is supposed, kept constantly burning there.\n\nThe Jews associated with this valley these two ideas, (1) that of the sufferings of the victims that had there been sacrificed; and (2) that of filth and corruption. It became thus to the popular mind a symbol of the abode of the wicked hereafter. It came to signify hell as the place of the wicked. “It might be shown by infinite examples that the Jews expressed hell, or the place of the damned, by this word. The word Gehenna [the Greek contraction of Hinnom] was never used in the time of Christ in any other sense than to denote the place of future punishment.” About this fact there can be no question. In this sense the word is used eleven times in our Lord’s discourses (Matt. 23:33; Luke 12:5; Matt. 5:22, etc.).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"7ee8123c682245b7808c7fdccb83d5ef9a0d0fabedbbfdc339bca997588eec49","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 15:8","Matt. 23:33","Luke 12:5","Matt. 5:22"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Hobah","source_key":"HOBAH","source_id":"k-HOBAH","source_text":"Hobah. Hobah\nHiding-place, a place to the north of Damascus, to which Abraham pursued Chedorlaomer and his confederates (Gen. 14:15).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"호바. 호바 은신처. 다메섹 북쪽에 있는 곳으로 아브라함이 그돌라오멜과 그 동맹자들을 그곳으로 추격하였다(창 14:15).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"8825b059f2fc914282cceb431942a8972907a7605ff7cece68493322d0ac73f6","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Gen. 14:15"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Horem","source_key":"HOREM","source_id":"k-HOREM","source_text":"Horem. Horem\nConsecrated, one of the fenced cities of Naphtali (Josh. 19:38).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"a5cdf671297818c99b533106549dcce7ef74da23174b4b48cf91fba977cf6f9f","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 19:38"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Hormah","source_key":"HORMAH","source_id":"k-HORMAH","source_text":"Hormah. Hormah\nBanning; i.e., placing under a “ban,” or devoting to utter destruction. After the manifestation of God’s anger against the Israelites, on account of their rebellion and their murmurings when the spies returned to the camp at Kadesh, in the wilderness of Paran, with an evil report of the land, they quickly repented of their conduct, and presumed to go up “to the head of the mountain,” seeking to enter the Promised Land, but without the presence of the Lord, without the ark of the convenant, and without Moses. The Amalekites and the Canaanites came down and “smote and discomfited them even unto Hormah” (Num. 14:45). This place, or perhaps the watch-tower commanding it, was originally called Zephath (Judg. 1:17), the modern Sebaiteh. Afterwards (Num. 21:1-3) Arad, the king of the Canaanites, at the close of the wanderings, when the Israelites were a second time encamped at Kadesh, “fought against them, and took some of them prisoners.” But Israel vowed a vow unto the Lord utterly to destroy the cities of the Canaanites; they “banned” them, and hence the place was now called Hormah. But this “ban” was not fully executed till the time of Joshua, who finally conquered the king of this district, so that the ancient name Zephath became “Hormah” (Josh. 12:14; Judg. 1:17).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"b6a51251f96fdd51d8b898dec85109b08b273651a540a3442991fe6c4b8d4d22","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Num. 14:45","Judg. 1:17","Num. 21:1-3","Josh. 12:14","Judg. 1:17"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Horonaim","source_key":"HORONAIM","source_id":"k-HORONAIM","source_text":"Horonaim. Horonaim\nTwo caverns, a city of Moab to the south of the Arnon, built, apparently, upon an eminence, and a place of some importance (Isa. 15:5; Jer. 48:3, 5, 34).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"호로나임. 호로나임 아르논 강 남쪽에 있는 모압의 도시인 두 개의 동굴은 분명 높은 곳에 세워졌고 어느 정도 중요한 장소였던 것 같습니다(사 15:5; 렘 48:3, 5, 34).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"d079026da8be7cd01a0a349c3bfed291f619d8e813e389772adbeb22d9733132","source_evidence":{"geographic_types":["settlement","site"],"scripture_citations_as_printed":["Isa. 15:5","Jer. 48:3"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Hukkok","source_key":"HUKKOK","source_id":"k-HUKKOK","source_text":"Hukkok. Hukkok\nDecreed, a town near Zebulun, not far from Jordan, on the border of Naphtali (Josh. 19:34). (See HELKATH.)","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"훅. 훅곡은 납달리 경계에 있는 요단에서 멀지 않은 스불론 근처의 성읍이다(수 19:34). (헬카스 참조)","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"ef65846e95af5c6290bbe70efe5c033aaa27ede42c62cecdca88fa957ed63da7","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:34"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Ibleam","source_key":"IBLEAM","source_id":"k-IBLEAM","source_text":"Ibleam. Ibleam\nPeople-waster, a city assigned to Manasseh (Josh. 17:11), from which the Israelites, however, could not expel the Canaanites (Judg. 1:27). It is also called Bileam (1 Chr. 6:70). It was probably the modern Jelamah, a village 2 1/2 miles north of Jenin.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"아이블림. 이블르암 백성을 황폐케 하는 성읍. 므낫세에게 할당된 성읍(수 17:11). 그러나 이스라엘 사람들은 그곳에서 가나안 사람들을 쫓아낼 수 없었다(삿 1:27). 빌암이라고도 불린다(대상 6:70). 그것은 아마도 Jenin에서 북쪽으로 2 1/2마일 떨어진 현대의 Jelamah 마을이었을 것입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"b744ef40f458b987eca097432eb28e5630cd11dbf50134198f819dc9c70b64db","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 17:11","Judg. 1:27","1 Chr. 6:70"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Idalah","source_key":"IDALAH","source_id":"k-IDALAH","source_text":"Idalah. Idalah\nSnares(?), a city near the west border of Zebulun (Josh. 19:15). It has been identified with the modern Jeida, in the valley of Kishon.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"이달라. 이다라 스나레스(?), 스불론 서쪽 경계에 가까운 성읍(수 19:15). 그것은 키손 계곡에 있는 현대의 제이다와 동일시된다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"18d6299c05d8586f6c404a1f77d085e93f2dc0514db2bbe325996488fcec5944","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:15"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Iim","source_key":"IIM","source_id":"k-IIM","source_text":"Iim. Iim\nRuins. (1.) A city in the south of Judah (Josh. 15:29).\n\n(2.) One of the stations of the Israelites in the wilderness (Num. 33:45).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"나는. 임 유적. (1) 유다 남쪽에 있는 도시(수 15:29). (2.) 광야에 있는 이스라엘 백성의 기지 중 하나(민 33:45).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"63d311ae397e229f7f0d69a4cc2a563f2d2f89571c148af8ac29d12801734006","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:29","Num. 33:45"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Jabneel","source_key":"JABNEEL","source_id":"k-JABNEEL","source_text":"Jabneel. Jabneel\nBuilt by God. (1.) A town in the north boundary of Judah (Josh. 15:11), called afterwards by the Greeks Jamnia, the modern Yebna, 11 miles south of Jaffa. After the fall of Jerusalem (A.D. 70), it became one of the most populous cities of Judea, and the seat of a celebrated school.\n\n(2.) A town on the border of Naphtali (Josh. 19:33). Its later name was Kefr Yemmah, “the village by the sea,” on the south shore of Lake Merom.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"얍닐. 하나님이 지으신 얍느엘. (1) 유다의 북쪽 경계에 있는 성읍(수 15:11). 나중에 그리스인들은 얌니아라고 불렀으며, 오늘날의 예브나는 욥바에서 남쪽으로 11마일 떨어져 있다. 예루살렘이 함락된 후(AD 70), 이곳은 유대에서 가장 인구가 많은 도시 중 하나이자 유명한 학교가 있는 곳이 되었습니다. (2) 납달리 국경에 있는 성읍(수 19:33). 나중에 그 이름은 케프르 예마(Kefr Yemmah), 즉 메롬 호수 남쪽 해안에 있는 “바닷가 마을”이었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"1d478000c31c4b1861ecb30c79799b6c68e4f1e68400ea3759d5354170ccbf8f","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:11","Josh. 19:33"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Jabneh","source_key":"JABNEH","source_id":"k-JABNEH","source_text":"Jabneh. Jabneh\nBuilding, (2 Chr. 26:6), identical with Jabneel (Josh. 15:11).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"f0d7082a64a34bdd4836b323c3da8d3be25ec8c7acdc1d25b951b2a8af2da6d2","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["2 Chr. 26:6","Josh. 15:11"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Janoah","source_key":"JANOAH","source_id":"k-JANOAH","source_text":"Janoah. Janoah\nOr Jano’hah, rest. (1.) A town on the north-eastern border of Ephraim, in the Jordan valley (Josh. 16:6, 7). Identified with the modern Yanun, 8 miles south-east of Nablus.\n\n(2.) A town of Northern Palestine, within the boundaries of Naphtali. It was taken by the king of Assyria (2 Kings 15:29).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"야노아. 자노아 아니면 자노하, 쉬세요. (1) 요단 골짜기에 있는 에브라임 북동쪽 경계에 있는 성읍(수 16:6, 7). 나블루스에서 남동쪽으로 8마일 떨어진 현대의 야눈(Yanun)과 동일시됩니다. (2.) 납달리 경계 내에 있는 북부 팔레스타인의 한 성읍. 앗수르 왕이 이를 함락시켰음(왕하 15:29)","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"b99c3526d34cfea32f019e2b02f599816ffb1eb0e723f9bcdbcfe19e35a646d0","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 16:6","2 Kings 15:29"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Jattir","source_key":"JATTIR","source_id":"k-JATTIR","source_text":"Jattir. Jattir\nPre-eminent, a city in the mountains of Judah (Josh. 15:48; 21:14).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"자티르. 유다 산지에 있는 도시 얏딜(수 15:48; 21:14).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"d3e4855aab81172b9e856da15ec7a9ce77cbd018d84bc63ed182c6c093030576","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:48"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Jebus","source_key":"JEBUS","source_id":"k-JEBUS","source_text":"Jebus. Jebus\nTrodden hard, or fastness, or “the waterless hill”, the name of the Canaanitish city which stood on Mount Zion (Josh. 15:8; 18:16, 28). It is identified with Jerusalem (q.v.) in Judg. 19:10, and with the castle or city of David (1 Chr. 11:4,5). It was a place of great natural strength, and its capture was one of David’s most brilliant achievements (2 Sam. 5:8).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"여부스. 여부스(Jebus)는 시온 산 위에 서 있던 가나안 도시의 이름인, 굳건함, 견고함 또는 “물 없는 산”을 밟았다(수 15:8; 18:16, 28). 이것은 사사기에서 예루살렘(q.v.)과 동일시된다. 19:10, 그리고 다윗의 성이나 도시와 함께(대상 11:4,5). 그곳은 자연의 힘이 매우 강한 곳이었으며 그곳을 함락시키는 일은 다윗이 이룩한 가장 빛나는 업적 중 하나였습니다(삼하 5:8).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"e29f19373ea990bb9e0b2b54a6a833cc9198ea66dfd35a64e5ed2546a8a5f0c0","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Josh. 15:8","Judg. 19:10","1 Chr. 11:4","2 Sam. 5:8"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Jeruel","source_key":"JERUEL","source_id":"k-JERUEL","source_text":"Jeruel. Jeruel\nFounded by God, a “desert” on the ascent from the valley of the Dead Sea towards Jerusalem. It lay beyond the wilderness of Tekoa, in the direction of Engedi (2 Chr. 20:16, 20). It corresponds with the tract of country now called el-Hasasah.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"60d9d9c326851a80aacbbb4ea1b3cd8025c9bb3ec469dc893e80fc629e22d0a4","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["2 Chr. 20:16"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Jeshanah","source_key":"JESHANAH","source_id":"k-JESHANAH","source_text":"Jeshanah. Jeshanah\nA city of the kingdom of Israel (2 Chr. 13:19).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"예샤나. 여사나 이스라엘 왕국의 성읍(대하 13:19).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"1244345b81da7370ed634121949584ba0faaee43abb279c0d23f4ecb5910c991","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["2 Chr. 13:19"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Jethlah","source_key":"JETHLAH","source_id":"k-JETHLAH","source_text":"Jethlah. Jethlah\nSuspended; high, a city on the borders of Dan (Josh. 19:42).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"제델라. Jethlah 정지; 높은 성, 단 경계에 있는 성읍(수 19:42).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"acb76f13a1c4cd51c4f1ac20a5ca6feb9dadb01d89cc293e732525225f78af39","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:42"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Jokmeam","source_key":"JOKMEAM","source_id":"k-JOKMEAM","source_text":"Jokmeam. Jokmeam\nGathering of the people, a city of Ephraim, which was given with its suburbs to the Levites (1 Chr. 6:68). It lay somewhere in the Jordan valley (1 Kings 4:12, R.V.; but in A.V. incorrectly “Jokneam”).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"족메암. 욕므암 백성이 모이는 에브라임 성읍. 레위 사람들에게 그 목초지와 함께 주어졌다(대상 6:68). 그것은 요단 계곡 어딘가에 놓여 있었다(왕상 4:12, R.V.; 그러나 A.V.에서는 \"욕느암\"으로 잘못 표기됨).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"4a44e05adc4bab661278786b6a27e04bded223a1d70a56e9db717e0e6b93a3d3","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["1 Chr. 6:68","1 Kings 4:12"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Jokneam","source_key":"JOKNEAM","source_id":"k-JOKNEAM","source_text":"Jokneam. Jokneam\nGathered by the people, (Josh. 19:11; 21:34), a city “of Carmel” (12:22), i.e., on Carmel, allotted with its suburbs to the Merarite Levites. It is the modern Tell Kaimon, about 12 miles south-west of Nazareth, on the south of the river Kishon.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"족넴. 욕느암 백성이 모여서(수 19:11; 21:34), “갈멜”(12:22) 성읍, 즉 갈멜에 있고 그 목초지와 함께 므라리 족속 레위 사람들에게 할당되었다. 그것은 나사렛에서 남서쪽으로 약 19km 떨어진 기손강 남쪽에 있는 현대의 텔카이몬입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"e501f45132dac414aca96a9e16bc4004054ab67037f97eec7bc39ec4ba9e3083","source_evidence":{"geographic_types":["river","settlement"],"scripture_citations_as_printed":["Josh. 19:11"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Kabzeel","source_key":"KABZEEL","source_id":"k-KABZEEL","source_text":"Kabzeel. Kabzeel\nGathering of God, a city in the extreme south of Judah, near to Idumaea (Josh. 15:21), the birthplace of Benaiah, one of David’s chief warriors (2 Sam. 23:20; 1 Chr. 11:22). It was called also Jekabzeel (Neh. 11:25), after the Captivity.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"Kabzeel. 갑스엘 하나님의 모임. 유다 최남단에 있는 도시로, 다윗의 대장군 중 한 명인 브나야의 출생지인 이두매아(수 15:21) 근처에 있다(삼하 23:20; 대상 11:22). 포로기 이후에는 여갑스엘(느 11:25)이라고도 불렸다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"045c8f0f9c4e104ee95b7ce78e46dd09a79804c6e7e40fc4cf8f2732d8d22e5d","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:21","2 Sam. 23:20","1 Chr. 11:22","Neh. 11:25"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Kadesh","source_key":"KADESH","source_id":"k-KADESH","source_text":"Kadesh. Kadesh\nThe sacred city of the Hittites, on the left bank of the Orontes, about 4 miles south of the Lake of Homs. It is identified with the great mound Tell Neby Mendeh, some 50 to 100 feet high, and 400 yards long. On the ruins of the temple of Karnak, in Egypt, has been found an inscription recording the capture of this city by Rameses II. (See PHARAOH.) Here the sculptor “has chiselled in deep work on the stone, with a bold execution of the several parts, the procession of the warriors, the battle before Kadesh, the storming of the fortress, the overthrow of the enemy, and the camp life of the Egyptians.” (See HITTITES.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":false},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"9c003f2f7bfd440c4f398129484e9c2475e307948ef1b1df9ef39b1aa9e34dca","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":[],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Karkaa","source_key":"KARKAA","source_id":"k-KARKAA","source_text":"Karkaa. Karkaa\nA floor; bottom, a place between Adar and Azmon, about midway between the Mediterranean and the Dead Sea (Josh. 15:3).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"카르카. 카르카 A층; 바닥은 아달과 아스몬 사이, 지중해와 사해의 중간쯤 되는 곳이다(수 15:3).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"f2070d9c0c2fc0615ef02e912f8927332445958235cac91fdd2bad59589d9ae6","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Josh. 15:3"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Karkor","source_key":"KARKOR","source_id":"k-KARKOR","source_text":"Karkor. Karkor\nFoundation, a place in the open desert wastes on the east of Jordan (Judg. 8:10), not far beyond Succoth and Penuel, to the south. Here Gideon overtook and routed a fugitive band of Midianites under Zeba and Zalmunna, whom he took captive.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"카르코르. 갈골 재단은 요단 동편(삿 8:10), 숙곳과 브누엘을 넘어 남쪽으로 그리 멀지 않은 탁 트인 사막 황무지에 있는 장소이다. 여기서 기드온은 세바와 살문나 휘하의 도망하는 미디안 무리를 따라잡아 패주시켰고, 그들을 포로로 잡았습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"95bd74b2ff9951b66bc843b5773237f10901f923653e95794888115056dc9e91","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Judg. 8:10"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Kartah","source_key":"KARTAH","source_id":"k-KARTAH","source_text":"Kartah. Kartah\nCity, a town in the tribe of Zebulun assigned to the Levites of the family of Merari (Josh. 21:34). It is identical with Kattath (19:15), and perhaps also with Kitron (Judg. 1:30).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"카르타. 가르다 성, 므라리 가족에 속한 레위 사람들에게 할당된 스불론 지파의 성읍(수 21:34). 이것은 갓닷(19:15)과 동일하며 아마도 기트론(삿 1:30)과도 동일할 것이다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"1bbd474579693561f4a8d3139f2b6166590a53372402ff0fe16dcf12d1bfde52","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 21:34","Judg. 1:30"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Keilah","source_key":"KEILAH","source_id":"k-KEILAH","source_text":"Keilah. Keilah\nCitadel, a city in the lowlands of Judah (Josh. 15:44). David rescued it from the attack of the Philistines (1 Sam. 23:1-8); but the inhabitants proving unfaithful to him, in that they sought to deliver him up to Saul (13), he and his men “departed from Keilah, and went whithersoever they could go.” They fled to the hill Hareth, about 3 miles to the east, and thence through Hebron to Ziph (q.v.). “And David was in the wilderness of Ziph, in a wood” (1 Sam. 23:15). Here Jonathan sought him out, “and strengthened his hand in God.” This was the last interview between David and Jonathan (23:16-18). It is the modern Khurbet Kila. Others identify it with Khuweilfeh, between Beit Jibrin (Eleutheropolis) and Beersheba, mentioned in the Amarna tablets.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"케일라. 유다 저지대에 있는 도시인 그일라 성채(수 15:44). 다윗은 블레셋 사람들의 공격으로부터 그 곳을 구해냈습니다(삼상 23:1-8). 그러나 주민들은 그에게 불충실하여 그를 사울에게 넘기려고 하였으므로(13) 그와 그의 사람들은 “그일라를 떠나 갈 수 있는 곳으로 갔다.” 그들은 동쪽으로 약 3 마일 떨어진 하렛 언덕으로 도망쳤고 거기서부터 헤브론을 거쳐 십(q.v.)에 이르렀습니다. “다윗이 십 광야 수풀에 있었더라”(삼상 23:15). 여기에서 요나단은 그를 찾아 “하나님 안에서 그의 손을 강하게 하였”습니다. 이것이 다윗과 요나단의 마지막 인터뷰였습니다(23:16-18). 현대의 Khurbet Kila입니다. 다른 사람들은 아마르나 서판에 언급된 Beit Jibrin(Eleutheropolis)과 Beersheba 사이에 있는 Khuweilfeh와 동일시합니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"6c4c86122acdf49cedf61a4eca4c56a653436f15fb950d2c7025abb8743d81c0","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:44","1 Sam. 23:1-8","1 Sam. 23:15"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Kerioth","source_key":"KERIOTH","source_id":"k-KERIOTH","source_text":"Kerioth. Kerioth\nCities. (1.) A town in the south of Judah (Josh. 15:25). Judas the traitor was probably a native of this place, and hence his name Iscariot. It has been identified with the ruins of el-Kureitein, about 10 miles south of Hebron. (See HAZOR [4]).\n\n(2.) A city of Moab (Jer. 48:24, 41), called Kirioth (Amos 2:2).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"가리옷. 가리옷 도시. (1) 유다 남쪽에 있는 성읍(수 15:25). 배반자 유다는 아마도 이곳 출신이었을 것이므로 그의 이름은 이스카리옷인 것 같습니다. 이곳은 헤브론에서 남쪽으로 약 10마일 떨어진 엘 쿠레이테인(el-Kureitein) 유적지와 동일시되었습니다. (위험 [4] 참조). (2) 기룐(암 2:2)이라고 불리는 모압의 도시(렘 48:24, 41).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"eaccea04ca0143c0abe57a792cf044f9aea743c4515f2a05dca8fa90d444870e","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:25","Jer. 48:24","Amos 2:2"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Kibroth-hattaavah","source_key":"KIBROTH-HATTAAVAH","source_id":"k-KIBROTH-HATTAAVAH","source_text":"Kibroth-hattaavah. Kibroth-hattaavah\nThe graves of the longing or of lust, one of the stations of the Israelites in the wilderness. It was probably in the Wady Murrah, and has been identified with the Erweis el-Ebeirig, where the remains of an ancient encampment have been found, about 30 miles north-east of Sinai, and exactly a day’s journey from ‘Ain Hudherah.\n\n“Here began the troubles of the journey. First, complaints broke out among the people, probably at the heat, the toil, and the privations of the march; and then God at once punished them by lightning, which fell on the hinder part of the camp, and killed many persons, but ceased at the intercession of Moses (Num. 11:1, 2). Then a disgust fell on the multitude at having nothing to eat but the manna day after day, no change, no flesh, no fish, no high-flavoured vegetables, no luscious fruits...The people loathed the ‘light food,’ and cried out to Moses, ‘Give us flesh, give us flesh, that we may eat.’” In this emergency Moses, in despair, cried unto God. An answer came. God sent “a prodigious flight of quails, on which the people satiated their gluttonous appetite for a full month. Then punishment fell on them: they loathed the food which they had desired; it bred disease in them; the divine anger aggravated the disease into a plague, and a heavy mortality was the consequence. The dead were buried without the camp; and in memory of man’s sin and of the divine wrath this name, Kibroth-hattaavah, the Graves of Lust, was given to the place of their sepulchre” (Num. 11:34, 35; 33:16, 17; Deut. 9:22; comp. Ps. 78:30, 31)., Rawlinson’s Moses, p. 175. From this encampment they journeyed in a north-eastern direction to Hazeroth.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"cffc6282e3a6b13e95f79812186b8e18eea677e80a564bb72ae4fb3e4271b691","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Num. 11:1","Num. 11:34","Deut. 9:22","Ps. 78:30"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Kirjath-jearim","source_key":"KIRJATH-JEARIM","source_id":"k-KIRJATH-JEARIM","source_text":"Kirjath-jearim. Kirjath-jearim\nCity of jaars; i.e., of woods or forests, a Gibeonite town (Josh. 9:17) on the border of Benjamin, to which tribe it was assigned (18:15, 28). The ark was brought to this place (1 Sam. 7:1, 2) from Beth-shemesh and put in charge of Abinadab, a Levite. Here it remained till it was removed by David to Jerusalem (2 Sam. 6:2, 3, 12; 1 Chr. 15:1-29; comp. Ps. 132). It was also called Baalah (Josh. 15:9) and Kirjath-baal (60). It has been usually identified with Kuriet el-‘Enab (i.e., “city of grapes”), among the hills, about 8 miles north-east of ‘Ain Shems (i.e., Beth-shemesh). The opinion, however, that it is to be identified with ‘Erma, 4 miles east of ‘Ain Shems, on the edge of the valley of Sorek, seems to be better supported. (See KIRJATH.)\n\nThe words of Ps. 132:6, “We found it in the fields of the wood,” refer to the sojourn of the ark at Kirjath-jearim. “Wood” is here the rendering of the Hebrew word jaar, which is the singular of jearim.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"e96475daad8a5df09496e55fc4a489c037ddc07b5e36897b1632bbb5c45f1083","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 9:17","1 Sam. 7:1","2 Sam. 6:2","1 Chr. 15:1-29","Josh. 15:9","Ps. 132:6"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Kishion","source_key":"KISHION","source_id":"k-KISHION","source_text":"Kishion. Kishion\nHardness, a city of Issachar assigned to the Gershonite Levites (Josh. 19:20), the same as Kishon (21:28).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"키시온. 기손(21:28)과 같은 게르손 레위 사람들에게 할당된 잇사갈의 도시 기시온 경도(수 19:20).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"5bae88a945a14e7a67b141e6144050ed06fbe43ad3f87b8e890d0dacebde7fa5","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:20"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Kitron","source_key":"KITRON","source_id":"k-KITRON","source_text":"Kitron. Kitron\nKnotty, a city of Zebulun (Judg. 1:30), called also Kattath (Josh. 19:15); supposed to be “Cana of Galilee.”","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"키트론. 스불론의 도시 키트론 노티(삿 1:30), 캇닷이라고도 불림(수 19:15); '갈릴리 가나'로 추정된다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"b1acfe09295470e1de02b4976eef6d2b11d789de1cb5a39006e00773a0e6a2fb","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Judg. 1:30","Josh. 19:15"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Lebonah","source_key":"LEBONAH","source_id":"k-LEBONAH","source_text":"Lebonah. Lebonah\nFrankincense, a town near Shiloh, on the north side of Bethel (Judg. 21:19). It has been identified with el-Lubban, to the south of Nablus.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"레보나. 벧엘 북쪽 실로 근처 성읍 르보나 유향(삿 21:19). 나블루스 남쪽의 엘루반(el-Lubban)으로 확인되었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"3e1fdee0188eff10e6e40c1bc6b1a11e1bdc623252f2b6ba6ed6b05c53a77d35","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Judg. 21:19"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Libnah","source_key":"LIBNAH","source_id":"k-LIBNAH","source_text":"Libnah. Libnah\nTransparency; whiteness. (1.) One of the stations of the Israelites in the wilderness (Num. 33:20, 21).\n\n(2.) One of the royal cities of the Canaanites taken by Joshua (Josh. 10:29-32; 12:15). It became one of the Levitical towns in the tribe of Judah (21:13), and was strongly fortified. Sennacherib laid siege to it (2 Kings 19:8; Isa. 37:8). It was the native place of Hamutal, the queen of Josiah (2 Kings 23:31). It stood near Lachish, and has been identified with the modern Arak el-Menshiyeh.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"881648051abd613f60fa5fce31d0197f012351b7e4063912d20d077820d4c5ea","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Num. 33:20","Josh. 10:29-32","2 Kings 19:8","Isa. 37:8","2 Kings 23:31"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Lo-debar","source_key":"LO-DEBAR","source_id":"k-LO-DEBAR","source_text":"Lo-debar. Lo-debar\nNo pasture, (2 Sam. 17:27), a town in Gilead not far from Mahanaim, north of the Jabbok (9:4, 5). It is probably identical with Debir (Josh. 13:26).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"로데바. 로드발 목초지 없음,(삼하 17:27), 얍복 북쪽 마하나임에서 멀지 않은 길르앗의 한 마을(9:4, 5). 이것은 아마도 드빌(수 13:26)과 동일할 것이다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"d3c52f108a6b2378d3bae59577d373ab09b97344ddce69e3b0471c30aa909f18","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["2 Sam. 17:27","Josh. 13:26"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Madmannah","source_key":"MADMANNAH","source_id":"k-MADMANNAH","source_text":"Madmannah. Madmannah\nDunghill, the modern el-Minyay, 15 miles south-south-west of Gaza (Josh. 15:31; 1 Chr. 2:49), in the south of Judah. The Pal. Mem., however, suggest Umm Deimneh, 12 miles north-east of Beersheba, as the site.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"d0de47a41dbe90bba743d1b70b313d57acc4f77456702fff49e5dd122a2b30ed","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 15:31","1 Chr. 2:49"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Madmen","source_key":"MADMEN","source_id":"k-MADMEN","source_text":"Madmen. Madmen\nIbid., a Moabite town threatened with the sword of the Babylonians (Jer. 48:2).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"de39a96b4bd93ad88dd67739c7a6eb6dba828ad07a7372d104e5be81d39e5e7f","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Jer. 48:2"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Madmenah","source_key":"MADMENAH","source_id":"k-MADMENAH","source_text":"Madmenah. Madmenah\nIbid., a town in Benjamin, not far from Jerusalem, towards the north (Isa. 10:31). The same Hebrew word occurs in Isa. 25:10, where it is rendered “dunghill.” This verse has, however, been interpreted as meaning “that Moab will be trodden down by Jehovah as teben [broken straw] is trodden to fragments on the threshing-floors of Madmenah.”","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"맛메나. 맛메나(Madmenah Ibid.)는 예루살렘에서 북쪽으로 멀지 않은 베냐민의 성읍이다(사 10:31). 동일한 히브리어 단어가 이사야서에도 나온다. 25:10, 여기서는 “똥더미”로 번역된다. 하지만 이 구절은 “마드메나의 타작마당에서 테벤[부러진 짚]이 밟혀 파편이 된 것처럼 모압도 여호와께 짓밟힐 것”이라는 의미로 해석되었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"c1c5af45415245b823df97822ae8e1625e73ceb33abb09abc069240097a83333","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Isa. 10:31","Isa. 25:10"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Magor-missabib","source_key":"MAGOR-MISSABIB","source_id":"k-MAGOR-MISSABIB","source_text":"Magor-missabib. Magor-missabib\nFear on every side, (Jer. 20:3), a symbolical name given to the priest Pashur, expressive of the fate announced by the prophet as about to come upon him. Pashur was to be carried to Babylon, and there die.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"eb8ab568e08d21cb31191866569af97dd4b0303e44efef765e7cfc800ccf4971","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Jer. 20:3"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Maon","source_key":"MAON","source_id":"k-MAON","source_text":"Maon. Maon\nHabitation, a town in the tribe of Judah, about 7 miles south of Hebron, which gave its name to the wilderness, the district round the conical hill on which the town stood. Here David hid from Saul, and here Nabal had his possessions and his home (1 Sam. 23:24, 25; 25:2). “Only some small foundations of hewn stone, a square enclosure, and several cisterns are now to be seen at Maon. Are they the remains of Nabal’s great establishment?” The hill is now called Tell M’ain.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"마온. 마온 거주지는 헤브론에서 남쪽으로 약 7마일 떨어진 유다 지파의 성읍으로, 그 성읍이 서 있는 원추형 언덕 둘레의 지역인 광야에서 그 이름을 얻었습니다. 여기서 다윗은 사울을 피해 숨었고, 나발은 그의 소유물과 집을 소유하고 있었습니다(삼상 23:24, 25; 25:2). \"이제 마온에는 다듬은 돌로 만든 몇 개의 작은 기초와 정사각형 성벽과 여러 개의 물탱크만 보일 뿐입니다. 그것들이 나발의 위대한 시설의 유적입니까?\" 이제 언덕은 Tell M'ain이라고 불립니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"692ec410af8532b9bfb9430dc6245c5a853fbbef610772f783526d68312e58cd","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["1 Sam. 23:24"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Maroth","source_key":"MAROTH","source_id":"k-MAROTH","source_text":"Maroth. Maroth\nBitterness; i.e., “perfect grief”, a place not far from Jerusalem; mentioned in connection with the invasion of the Assyrian army (Micah 1:12).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":false},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"672e86d4ed0b9587de3aaba76299c72540e5861673609dcecbe838252aa6c635","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":[],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Massah","source_key":"MASSAH","source_id":"k-MASSAH","source_text":"Massah. Massah\nTrial, temptation, a name given to the place where the Israelites, by their murmuring for want of water, provoked Jehovah to anger against them. It is also called Meribah (Ex. 17:7; Deut. 6:16; Ps. 95:8, 9; Heb. 3:8).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"d959d638d2f584f78a6dcba4d9edbd0e21bb3057f4ef4a614e96bf8db247ef45","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Ex. 17:7","Deut. 6:16","Ps. 95:8"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Medeba","source_key":"MEDEBA","source_id":"k-MEDEBA","source_text":"Medeba. Medeba\nWaters of quiet, an ancient Moabite town (Num. 21:30). It was assigned to the tribe of Reuben (Josh. 13:16). Here was fought the great battle in which Joab defeated the Ammonites and their allies (1 Chr. 19:7-15; comp. 2 Sam. 10:6-14). In the time of Isaiah (15:2) the Moabites regained possession of it from the Ammonites. (See HANUN.)\n\nThe ruins of this important city, now Madeba or Madiyabah, are seen about 8 miles south-west of Heshbon, and 14 east of the Dead Sea. Among these are the ruins of what must have been a large temple, and of three cisterns of considerable extent, which are now dry. These cisterns may have originated the name Medeba, “waters of quiet.” (See OMRI.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"547b9a58e82ef48459eee9e74df93df8dcad8290f9f050052470ff44b493d679","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Num. 21:30","Josh. 13:16","1 Chr. 19:7-15","2 Sam. 10:6-14"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Me-jarkon","source_key":"ME-JARKON","source_id":"k-ME-JARKON","source_text":"Me-jarkon. Me-jarkon\nWaters of yellowness, or clear waters, a river in the tribe of Dan (Josh. 19:46). It has been identified with the river ‘Aujeh, which rises at Antipatris.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"Me-jarkon. 메얄콘 황색 물 또는 맑은 물, 단 지파에 속한 강(수 19:46). 그것은 안티파트리스(Antipatris)에서 솟아오르는 아우제(Aujeh) 강과 동일시되었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"aa01400b020c6f7aa562a8b37dee3b79da5bb2b8220133e8441420113f777c29","source_evidence":{"geographic_types":["river"],"scripture_citations_as_printed":["Josh. 19:46"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Mephibosheth","source_key":"MEPHIBOSHETH","source_id":"k-MEPHIBOSHETH","source_text":"Mephibosheth. Mephibosheth\nExterminator of shame; i.e., of idols. (1.) The name of Saul’s son by the concubine Rizpah (q.v.), the daughter of Aiah. He and his brother Armoni were with five others “hanged on a hill before the Lord” by the Gibeonites, and their bodies exposed in the sun for five months (2 Sam. 21:8-10). (2.) The son of Jonathan, and grandson of Saul (2 Sam. 4:4). He was but five years old when his father and grandfather fell on Mount Gilboa. The child’s nurse hearing of this calamity, fled with him from Gibeah, the royal residence, and stumbling in her haste, the child was thrown to the ground and maimed in both his feet, and ever after was unable to walk (19:26). He was carried to the land of Gilead, where he found a refuge in the house of Machir, the son of Ammiel, at Lo-debar, by whom he was brought up.\n\nSome years after this, when David had subdued all the adversaries of Israel, he began to think of the family of Jonathan, and discovered that Mephibosheth was residing in the house of Machir. Thither he sent royal messengers, and brought him and his infant son to Jerusalem, where he ever afterwards resided (2 Sam. 9).\n\nWhen David was a fugitive, according to the story of Ziba (2 Sam. 16:1-4) Mephibosheth proved unfaithful to him, and was consequently deprived of half of his estates; but according to his own story, however (19:24-30), he had remained loyal to his friend. After this incident he is only mentioned as having been protected by David against the vengeance the Gibeonites were permitted to execute on the house of Saul (21:7). He is also called Merib-baal (1 Chr. 8:34; 9:40). (See ZIBA.)","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"므비보셋. 므비보셋은 수치심을 없애는 자입니다. 즉, 우상의. (1) 아야의 딸인 첩 리스바가 낳은 사울의 아들의 이름. 그와 그의 형제 알모니는 다른 다섯 사람과 함께 기브온 사람들에 의해 “여호와 앞 산에 달려” 있었고 그들의 몸은 다섯 달 동안 햇빛에 노출되었습니다(삼하 21:8-10). (2.) 요나단의 아들이자 사울의 손자(삼하 4:4). 그의 아버지와 할아버지가 길보아 산에 떨어졌을 때 그는 겨우 다섯 살이었습니다. 이 재앙을 듣고 아이의 유모가 왕궁 기브아에서 그와 함께 도망하여 급히 비틀거리니 아이가 땅에 던져져 두 발이 다쳤고 그 후로 걷지 못하게 되었더라(19:26). 그는 길르앗 땅으로 끌려가 그곳에서 암미엘의 아들 마길의 집에 피난처를 찾았습니다. 그를 키워준 로데바르. 그로부터 몇 년 후에 다윗이 이스라엘의 모든 대적을 굴복시킨 후에 요나단의 가족을 생각하다가 므비보셋이 마길의 집에 거하는 것을 알게 되었더라. 그는 그곳으로 왕의 사자를 보냈고 그와 그의 어린 아들을 예루살렘으로 데리고 갔는데, 그곳은 그가 이후에 거주했던 곳이었습니다(삼하 9장). 시바의 이야기에 따르면 다윗이 도망자였을 때(삼하 16:1-4) 므비보셋은 그에게 불충실한 것으로 판명되었고 결과적으로 그의 재산의 절반을 박탈당했습니다. 그러나 그 자신의 이야기에 따르면(19:24-30), 그는 친구에게 충성을 유지했습니다. 이 사건 이후 그는 기브온 사람들이 사울의 집에 처형하도록 허락받은 복수에 맞서 다윗에 의해 보호받은 것으로만 언급됩니다(21:7). 그는 또한 므립바알(대상 8:34; 9:40). (지바 참조)","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"37304b93e73537c48f7f782539913fbb2fc4ca271c8a321c96041c23359f7be5","source_evidence":{"geographic_types":["mountain"],"scripture_citations_as_printed":["2 Sam. 21:8-10","2 Sam. 4:4","2 Sam. 16:1-4","1 Chr. 8:34"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Meribah","source_key":"MERIBAH","source_id":"k-MERIBAH","source_text":"Meribah. Meribah\nQuarrel or strife. (1.) One of the names given by Moses to the fountain in the desert of Sin, near Rephidim, which issued from the rock in Horeb, which he smote by the divine command, “because of the chiding of the children of Israel” (Ex. 17:1-7). It was also called Massah (q.v.). It was probably in Wady Feiran, near Mount Serbal.\n\n(2.) Another fountain having a similar origin in the desert of Zin, near to Kadesh (Num. 27:14). The two places are mentioned together in Deut. 33:8. Some think the one place is called by the two names (Ps. 81:7). In smiting the rock at this place Moses showed the same impatience as the people (Num. 20:10-12). This took place near the close of the wanderings in the desert (Num. 20:1-24; Deut. 32:51).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"9d99903c2879f850ae772d7c667acc628e3d310381eca500fc6e60a04a1991ec","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Ex. 17:1-7","Num. 27:14","Deut. 33:8","Ps. 81:7","Num. 20:10-12","Num. 20:1-24","Deut. 32:51"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Merom","source_key":"MEROM","source_id":"k-MEROM","source_text":"Merom. Merom\nHeight, a lake in Northern Palestine through which the Jordan flows. It was the scene of the third and last great victory gained by Joshua over the Canaanites (Josh. 11:5-7). It is not again mentioned in Scripture. Its modern name is Bakrat el-Huleh. “The Ard el-Huleh, the centre of which the lake occupies, is a nearly level plain of 16 miles in length from north to south, and its breadth from east to west is from 7 to 8 miles. On the west it is walled in by the steep and lofty range of the hills of Kedesh-Naphtali; on the east it is bounded by the lower and more gradually ascending slopes of Bashan; on the north it is shut in by a line of hills hummocky and irregular in shape and of no great height, and stretching across from the mountains of Naphtali to the roots of Mount Hermon, which towers up at the north-eastern angle of the plain to a height of 10,000 feet. At its southern extremity the plain is similarly traversed by elevated and broken ground, through which, by deep and narrow clefts, the Jordan, after passing through Lake Huleh, makes its rapid descent to the Sea of Galilee.”\n\nThe lake is triangular in form, about 4 1/2 miles in length by 3 1/2 at its greatest breadth. Its surface is 7 feet above that of the Mediterranean. It is surrounded by a morass, which is thickly covered with canes and papyrus reeds, which are impenetrable. Macgregor with his canoe, the Rob Roy, was the first that ever, in modern times, sailed on its waters. (See JORDAN.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"ea45938744b4690add3a1fef8a5bb403eeaf7727dd022fa4f562aba56124cf13","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 11:5-7"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Michmash","source_key":"MICHMASH","source_id":"k-MICHMASH","source_text":"Michmash. Michmash\nSomething hidden, a town of Benjamin (Ezra 2:27), east of Bethel and south of Migron, on the road to Jerusalem (Isa. 10:28). It lay on the line of march of an invading army from the north, on the north side of the steep and precipitous Wady es-Suweinit (“valley of the little thorn-tree” or “the acacia”), and now bears the name of Mukhmas. This wady is called “the passage of Michmash” (1 Sam. 13:23). Immediately facing Mukhmas, on the opposite side of the ravine, is the modern representative of Geba, and behind this again are Ramah and Gibeah.\n\nThis was the scene of a great battle fought between the army of Saul and the Philistines, who were utterly routed and pursued for some 16 miles towards Philistia as far as the valley of Aijalon. “The freedom of Benjamin secured at Michmash led through long years of conflict to the freedom of all its kindred tribes.” The power of Benjamin and its king now steadily increased. A new spirit and a new hope were now at work in Israel. (See SAUL.)","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"Michmash. 믹마스 벧엘 동쪽, 미그론 남쪽, 예루살렘으로 가는 길(사 10:28)에 있는 베냐민의 성읍(스 2:27)에 숨겨진 것. 그것은 가파르고 가파른 Wady es-Suweinit(“작은 가시나무 계곡” 또는 “아카시아”)의 북쪽, 북쪽에서 침략하는 군대의 행군 선에 놓여 있었고 지금은 Mukhmas라는 이름을 갖고 있습니다. 이 와디는 “믹마스 통로”라고 불린다(삼상 13:23). 계곡 반대편 무크마스 바로 앞에는 현대의 게바 대표자가 있고, 그 뒤에는 다시 라마와 기브아가 있다. 이것은 사울의 군대와 블레셋 사람들 사이에 큰 전투가 벌어졌던 장면인데, 블레셋 사람들은 완전히 패하고 블레셋을 향해 아얄론 골짜기까지 약 16 마일을 추격했습니다. “베냐민의 자유가 보장되었습니다. Michmash는 오랜 세월의 갈등을 통해 모든 동족 부족의 자유를 얻었습니다.” 이제 베냐민과 그 왕의 세력은 꾸준히 커졌습니다. 이제 새로운 영과 새로운 희망이 이스라엘에 역사하고 있었습니다. (사울 참조)","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"b6207a0d3d4c85ac6496a7e210218fdee1b1a99121f93ab819416103bdb8e678","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Ezra 2:27","Isa. 10:28","1 Sam. 13:23"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Michmethah","source_key":"MICHMETHAH","source_id":"k-MICHMETHAH","source_text":"Michmethah. Michmethah\nHiding-place, a town in the northern border of Ephraim and Manasseh, and not far west of Jordan (Josh. 16:6; 17:7).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"믹메타. 믹메다 은신처, 에브라임과 므낫세 북쪽 경계에 있는 성읍, 요단 서쪽에서 멀지 않은 곳(수 16:6; 17:7).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"108624ffa6ee305970f790b5962b0ce21349d6c842f76b71c0b6359f69db1bac","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 16:6"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Migdal-edar","source_key":"MIGDAL-EDAR","source_id":"k-MIGDAL-EDAR","source_text":"Migdal-Edar. Migdal-Edar\nTower of the flock, a place 2 miles south of Jerusalem, near the Bethlehem road (Gen. 35:21). (See EDAR.)","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"Migdal-Edar. 믹달-에달 양떼의 탑, 베들레헴 도로 근처, 예루살렘에서 남쪽으로 2마일 떨어진 장소(창 35:21). (EDAR 참조)","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"b6aa380922921a1a699d451d6fb7f32d6e5cb607bba15223aa23f47b1be7f1ab","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Gen. 35:21"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Migdal-gad","source_key":"MIGDAL-GAD","source_id":"k-MIGDAL-GAD","source_text":"Migdal-gad. Migdal-gad\nTower of fortune, a town in the plains of Judah, probably the modern el-Mejdel, a little to the north-east of Ascalon (Josh. 15:37).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"믹달갓. 믹달갓(Migdal-gad) 행운의 탑, 유다 평야에 있는 성읍, 아마도 아스갈론의 북동쪽에 조금 있는 현대의 엘메델(수 15:37).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"dcfaae5b7e61db702b77626137913c1fefbe1bad90cefa887d2337c956eb3153","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:37"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Migdol","source_key":"MIGDOL","source_id":"k-MIGDOL","source_text":"Migdol. Migdol\nTower. (1.) A strongly-fortified place 12 miles from Pelusium, in the north of Egypt (Jer. 44:1; 46:14). This word is rendered “tower” in Ezek. 29:10, but the margin correctly retains the name Migdol, “from Migdol to Syene;” i.e., from Migdol in the north to Syene in the south, in other words, the whole of Egypt.\n\n(2.) A place mentioned in the passage of the Red Sea (Ex. 14:2; Num. 33:7, 8). It is probably to be identified with Bir Suweis, about 2 miles from Suez.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"미그돌. 미그돌타워. (1) 애굽 북쪽 펠루시움에서 19km 떨어진 견고한 요새지(렘 44:1; 46:14). 이 단어는 에스겔서에서 “망대”로 번역됩니다. 29:10, 그러나 여백에는 “믹돌에서 수에네까지”라는 뜻의 믹돌이라는 이름이 정확하게 남아 있다. 즉, 북쪽의 믹돌부터 남쪽의 수에네까지, 즉 이집트 전체를 의미합니다. (2.) 홍해를 건널 때 언급된 장소(출 14:2; 민 33:7, 8). 아마도 수에즈에서 약 3.2km 떨어진 비르 수웨이스(Bir Suweis)로 확인될 것입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"db384c25f215a94dad2ce5e45fd6a1da26e745c912854db50048519127d05ea9","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Jer. 44:1","Ezek. 29:10","Ex. 14:2","Num. 33:7"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Minnith","source_key":"MINNITH","source_id":"k-MINNITH","source_text":"Minnith. Minnith\nDistribution, an Ammonitish town (Judg. 11:33) from which wheat was exported to Tyre (Ezek. 27:17). It was probably somewhere in the Mishor or table-land on the east of Jordan. There is a gentle valley running for about 4 miles east of Dhiban called Kurm Dhiban, “the vineyards of Dibon.” Tristram supposes that this may be the “vineyards” mentioned in Judg. (l.c.).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"1837eb341ddce3e25303b640697c844e9dcd2425b78c887928c151013bacbc4c","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Judg. 11:33","Ezek. 27:17"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Mozah","source_key":"MOZAH","source_id":"k-MOZAH","source_text":"Mozah. Mozah\nAn issuing of water, a city of Benjamin (Josh. 18:26).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"모자. 모사 안이 베냐민의 성읍에 물을 내는 일(수 18:26).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"6b95c987a42b38d3be3aab4d83ef730ad8a33b99cebd4b79abac2c2a5a58cf03","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 18:26"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Naarah","source_key":"NAARAH","source_id":"k-NAARAH","source_text":"Naarah. Naarah\nA girl, the second of Ashur’s two wives, of the tribe of Judah (1 Chr. 4:5, 6).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"4afa39326327eda08876249e60d2c15b01f1f6af3e978964085428c4e6925995","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["1 Chr. 4:5"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Naaran","source_key":"NAARAN","source_id":"k-NAARAN","source_text":"Naaran. Naaran\nBoyish, juvenile, a town in Ephraim between Bethel and Jericho (1 Chr. 7:28).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"나아란. 나아란 보이쉬(Naaran Boyish), 소년, 벧엘과 여리고 사이 에브라임의 한 마을(대상 7:28).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"6ca8c3b53768c837bdc0c3517849ec2c091e18d413635af2d8dfb9445f866083","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["1 Chr. 7:28"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Nahallal","source_key":"NAHALLAL","source_id":"k-NAHALLAL","source_text":"Nahallal. Nahallal\nPasture, a city in Zebulun on the border of Issachar (Josh. 19:15), the same as Nahalol (Judg. 1:30). It was given to the Levites. It has been by some identified with Malul in the plain of Esdraelon, 4 miles from Nazareth.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"나할랄. 나할랄 목초지, 잇사갈 경계에 있는 스불론에 있는 도시(수 19:15). 나할롤(삿 1:30)과 동일함. 레위인들에게 주어졌습니다. 일부 사람들은 그곳이 나사렛에서 4마일 떨어진 에스드라엘론 평야에 있는 말룰과 동일시되었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"06acebfc4d5066fcf3e3950910bfda204f467b8c048d757d1301d919d4dcd95a","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:15","Judg. 1:30"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Nahaliel","source_key":"NAHALIEL","source_id":"k-NAHALIEL","source_text":"Nahaliel. Nahaliel\nPossession, or valley of God, one of the encampments of the Israelites in the wilderness (Num. 21:19), on the confines of Moab. This is identified with the ravine of the Zerka M’ain, the ancient Callirhoe, the hot springs on the east of the Jordan, not far from the Dead Sea.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"e8a03ca4484f08ab6b8e8636a3b1b530cd799874564bf0233033801b4e66dff9","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Num. 21:19"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Neapolis","source_key":"NEAPOLIS","source_id":"k-NEAPOLIS","source_text":"Neapolis. Neapolis\nNew city, a town in Thrace at which Paul first landed in Europe (Acts 16:11). It was the sea-port of the inland town of Philippi, which was distant about 10 miles. From this port Paul embarked on his last journey to Jerusalem (Acts 20:6). It is identified with the modern Turco-Grecian Kavalla.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"네아폴리스. 네아폴리스 새로운 도시, 바울이 처음으로 유럽에 상륙한 트라키아의 도시(행 16:11). 그곳은 약 10마일 떨어진 내륙 도시 빌립보의 항구였습니다. 이 항구에서 바울은 예루살렘으로 향하는 마지막 여행을 떠났다(행 20:6). 그것은 현대의 투르코-그리스식 카발라(Kavalla)와 동일시된다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"299ee1cb300142ba4884bb1a6d45aeb2064878d5ca01a6c8ec40c8d6eb86b47c","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Acts 16:11","Acts 20:6"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Netophah","source_key":"NETOPHAH","source_id":"k-NETOPHAH","source_text":"Netophah. Netophah\nDistillation; dropping, a town in Judah, in the neighbourhood, probably, of Bethlehem (Neh. 7:26; 1 Chr. 2:54). Two of David’s guards were Netophathites (1 Chr. 27:13, 15). It has been identified with the ruins of Metoba, or Um Toba, to the north-east of Bethlehem.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"네토파. 네토파 증류; 유다의 한 성읍, 아마도 베들레헴 근처였을 것이다(느 7:26; 대상 2:54). 다윗의 경비병 중 두 명은 느도바 사람들이었습니다(대상 27:13, 15). 그것은 베들레헴 북동쪽에 있는 메토바(Metoba) 또는 움 토바(Um Toba)의 폐허와 동일시됩니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"56502b3728e2ee3c400b660d6e25e02dde9eb12cdc31221e9486d66a552bae05","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Neh. 7:26","1 Chr. 2:54","1 Chr. 27:13"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Nicopolis","source_key":"NICOPOLIS","source_id":"k-NICOPOLIS","source_text":"Nicopolis. Nicopolis\nCity of victory, where Paul intended to winter (Titus 3:12). There were several cities of this name. The one here referred to was most probably that in Epirus, which was built by Augustus Caesar to commemorate his victory at the battle of Actium (B.C. 31). It is the modern Paleoprevesa, i.e., “Old Prevesa.” The subscription to the epistle to Titus calls it “Nicopolis of Macedonia”, i.e., of Thrace. This is, however, probably incorrect.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":false},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"a74d49da86a691230eab6e94460578177d76c16b275b3b8ce88b410e7a5801c6","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":[],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Nimrah","source_key":"NIMRAH","source_id":"k-NIMRAH","source_text":"Nimrah. Nimrah\nPure, a city on the east of Jordan (Num. 32:3); probably the same as Beth-nimrah (Josh. 13:27). It has been identified with the Nahr Nimrin, at one of the fords of Jordan, not far from Jericho.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"니므라. 요단 동쪽에 있는 도시 니므라 퓨레(민 32:3); 아마도 벳-니므라(수 13:27)와 동일할 것이다. 그것은 예리코에서 멀지 않은 요르단의 여울목 중 하나에 있는 나흐르 님린과 동일시되었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"15290dcdd6b2af32ca3ca26d9c4ff7a7f825e05020881e5ede15d97c774e652f","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Num. 32:3","Josh. 13:27"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Noph","source_key":"NOPH","source_id":"k-NOPH","source_text":"Noph. Noph\nThe Hebrew name of an Egyptian city (Isa. 19:13; Jer.2:16; 44:1; 46:14, 19; Ezek. 30:13, 16). In Hos. 9:6 the Hebrew name is Moph, and is translated “Memphis,” which is its Greek and Latin form. It was one of the most ancient and important cities of Egypt, and stood a little to the south of the modern Cairo, on the western bank of the Nile. It was the capital of Lower Egypt. Among the ruins found at this place is a colossal statue of Rameses the Great. (See MEMPHIS.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"3faa4711183e15589f6857f3cb196e50cad472b0b1fa66d7f2b95f898591eda7","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Isa. 19:13","Jer.2:16","Ezek. 30:13","Hos. 9:6"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Oboth","source_key":"OBOTH","source_id":"k-OBOTH","source_text":"Oboth. Oboth\nBottles, an encampment of the Israelites during the wanderings in the wilderness (Num. 33:43), the first after the setting up of the brazen serpent.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"5b2f4d04529b78d27601ec1ce333acfae8921d5d60f924b2daf661235bc46403","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Num. 33:43"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Ono","source_key":"ONO","source_id":"k-ONO","source_text":"Ono. Ono\nA town of Benjamin, in the “plain of Ono” (1 Chr. 8:12; Ezra 2:33); now Kefr ‘Ana, 5 miles north of Lydda, and about 30 miles north-west of Jerusalem. Not succeeding in their attempts to deter Nehemiah from rebuilding the walls of Jerusalem, Sanballat and Tobiah resorted to strategem, and pretending to wish a conference with him, they invited him to meet them at Ono. Four times they made the request, and every time Nehemiah refused to come. Their object was to take him prisoner.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"오노. 오노 “오노 평지”에 있는 베냐민의 성읍(대상 8:12; 에스라 2:33); 현재 Kefr 'Ana는 Lydda에서 북쪽으로 5마일, 예루살렘에서 북서쪽으로 약 30마일 떨어져 있습니다. 느헤미야가 예루살렘 성벽을 재건하는 것을 막으려는 시도가 실패하자 산발랏과 도비야는 계략을 써서 그와 회담을 갖고 싶은 척하며 오노에서 만나자고 느헤미야를 초대했습니다. 그들은 네 번이나 요청했지만 느헤미야는 매번 오기를 거절했습니다. 그들의 목적은 그를 포로로 잡는 것이었다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"68a330981dfb1e7d78c2ec86b0e49cf1c07d5bc57adb8da01b63b99ba0df41e3","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["1 Chr. 8:12","Ezra 2:33"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Ophrah","source_key":"OPHRAH","source_id":"k-OPHRAH","source_text":"Ophrah. Ophrah\nA fawn. 1 Chr. 4:14. (1.) A city of Benjamin (Josh. 18:23); probably identical with Ephron (2 Chr. 13:19) and Ephraim (John 11:54).\n\n(2.) “Of the Abi-ezrites.” A city of Manasseh, 6 miles south-west of Shechem, the residence of Gideon (Judg. 6:11; 8:27, 32). After his great victory over the Midianites, he slew at this place the captive kings (8:18-21). He then assumed the function of high priest, and sought to make Ophrah what Shiloh should have been. This thing “became a snare” to Gideon and his house. After Gideon’s death his family resided here till they were put to death by Abimelech (Judg. 9:5). It is identified with Ferata.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"오프라. 오프라 새끼 사슴. 1월 4:14. (1) 베냐민의 성(수 18:23); 아마도 에브론(대하 13:19)과 에브라임(요 11:54)과 동일할 것이다. (2.) “아비에셀 족속의.” 기드온이 거주했던 세겜에서 남서쪽으로 6마일 떨어진 므낫세의 도시(삿 6:11; 8:27, 32). 미디안 사람들에게 큰 승리를 거둔 후, 그는 이곳에서 포로된 왕들을 죽였습니다(8:18-21). 그런 다음 그는 대제사장의 역할을 맡아 오브라를 실로와 같이 만들려고 노력했습니다. 이 일이 기드온과 그의 집에 “올무가 되었”습니다. 기드온이 죽은 후 그의 가족은 아비멜렉에게 죽임을 당할 때까지 이곳에 거주했습니다(삿 9:5). Ferata로 식별됩니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"758771cd336066cebcc8354b08383ef103038ec23bb5d6920945098aba100f08","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["1 Chr. 4:14","Josh. 18:23","2 Chr. 13:19","John 11:54","Judg. 6:11","Judg. 9:5"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Padan-aram","source_key":"PADAN-ARAM","source_id":"k-PADAN-ARAM","source_text":"Padan-aram. Padan-aram\nThe plain of Aram, or the plain of the highlands, (Gen. 25:20; 28:2, 5-7; 31:18, etc.), commonly regarded as the district of Mesopotamia (q.v.) lying around Haran.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"5d3aa9a6804c543a8ae43ecbaf133fa9eeab57abfe1d92680242617bc0aa1be0","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Gen. 25:20"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Pamphylia","source_key":"PAMPHYLIA","source_id":"k-PAMPHYLIA","source_text":"Pamphylia. Pamphylia\nPaul and his company, loosing from Paphos, sailed north-west and came to Perga, the capital of Pamphylia (Acts 13:13, 14), a province about the middle of the southern sea-board of Asia Minor. It lay between Lycia on the west and Cilicia on the east. There were strangers from Pamphylia at Jerusalem on the day of Pentecost (2:10).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"팜필리아. 밤빌리아 바울과 그의 일행은 바보에서 항해하여 북서쪽으로 항해하여 소아시아 남해안 중앙쯤에 있는 속주인 밤빌리아의 수도 버가에 도착했습니다(행 13:13, 14). 서쪽의 리기아와 동쪽의 길리기아 사이에 있었습니다. 오순절 날 밤빌리아에서 온 나그네들이 예루살렘에 있었습니다(2:10).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"9688b30ad64f16e3a963955215bcec5c44bf4f3ce8b72c7a865ea0f671b69f17","source_evidence":{"geographic_types":["region"],"scripture_citations_as_printed":["Acts 13:13"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Paran","source_key":"PARAN","source_id":"k-PARAN","source_text":"Paran. Paran\nAbounding in foliage, or abounding in caverns, (Gen. 21:21), a desert tract forming the north-eastern division of the peninsula of Sinai, lying between the ‘Arabah on the east and the wilderness of Shur on the west. It is intersected in a north-western direction by the Wady el-‘Arish. It bears the modern name of Badiet et-Tih, i.e., “the desert of the wanderings.” This district, through which the children of Israel wandered, lay three days’ march from Sinai (Num. 10:12, 33). From Kadesh, in this wilderness, spies (q.v.) were sent to spy the land (13:3, 26). Here, long afterwards, David found refuge from Saul (1 Sam. 25:1, 4).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"53f41504b76c8713254c4bebd9990f615299aa3ed1838dfabf393dea55ff65cd","source_evidence":{"geographic_types":["region"],"scripture_citations_as_printed":["Gen. 21:21","Num. 10:12","1 Sam. 25:1"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Paphos","source_key":"PAPHOS","source_id":"k-PAPHOS","source_text":"Paphos. Paphos\nThe capital of the island of Cyprus, and therefore the residence of the Roman governor. It was visited by Paul and Barnabas on their first missionary tour (Acts 13:6). It is new Paphos which is here meant. It lay on the west coast of the island, about 8 miles north of old Paphos. Its modern name is Baffa.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"773aa9a5c15e90d63da752b3841c0ee589ebe996f782a828d28f3124cfe41334","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Acts 13:6"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Pekod","source_key":"PEKOD","source_id":"k-PEKOD","source_text":"Pekod. Pekod\nProbably a place in Babylonia (Jer. 50:21; Ezek. 23:23). It is the opinion, however, of some that this word signifies “visitation,” “punishment,” and allegorically “designates Babylon as the city which was to be destroyed.”","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"페코드. 브곳은 아마도 바빌로니아에 있는 장소였을 것이다(렘 50:21; 겔 23:23). 그러나 일부 사람들은 이 단어가 “형벌”, “형벌”을 의미하고 비유적으로 “멸망될 성읍 바벨론을 가리킨다”고 생각합니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"53c66bf96c9a98152598014ce471310cff709ba52ffb35dd61f91e223b3203a8","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Jer. 50:21","Ezek. 23:23"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Peor","source_key":"PEOR","source_id":"k-PEOR","source_text":"Peor. Peor\nOpening. (1.) A mountain peak (Num. 23:28) to which Balak led Balaam as a last effort to induce him to pronounce a curse upon Israel. When he looked on the tribes encamped in the acacia groves below him, he could not refrain from giving utterance to a remarkable benediction (24:1-9). Balak was more than ever enraged at Balaam, and bade him flee for his life. But before he went he gave expression to that wonderful prediction regarding the future of this mysterious people, whose “goodly tents” were spread out before him, and the coming of a “Star” out of Jacob and a “Sceptre” out of Israel (24:14-17).\n\n(2.) A Moabite divinity, called also “Baal-peor” (Num. 25:3, 5, 18; comp. Deut. 3:29).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"피오르. 피어 오프닝. (1) 발락이 이스라엘을 저주하도록 유도하기 위한 마지막 노력으로 발락이 발람을 이끌었던 산봉우리(민 23:28). 그는 자기 아래 아카시아 숲에 진을 치고 있는 지파들을 바라보면서 놀라운 축복의 말을 하지 않을 수 없었습니다(24:1-9). 발락은 발람에게 그 어느 때보다 격분하여 도망하여 목숨을 구하라고 명했습니다. 그러나 그가 가기 전에 그는 그 앞에 “좋은 장막”이 펼쳐져 있는 이 신비스러운 백성의 미래와 야곱에게서는 “별”이, 이스라엘에게서는 “홀”이 나올 것에 관한 놀라운 예언을 표현했습니다(24:14-17). (2.) “바알브올”이라고도 불리는 모압의 신. (민 25:3, 5, 18; 신 3:29을 비교하라)","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"7216724068c62320cb003ff92bd1d9048fa6b92094c35f4826572b49aa2c6876","source_evidence":{"geographic_types":["mountain"],"scripture_citations_as_printed":["Num. 23:28","Num. 25:3","Deut. 3:29"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Perga","source_key":"PERGA","source_id":"k-PERGA","source_text":"Perga. Perga\nThe capital of Pamphylia, on the coast of Asia Minor. Paul and his companions landed at this place from Cyprus on their first missionary journey (Acts 13:13, 14), and here Mark forsook the party and returned to Jerusalem. Some time afterwards Paul and Barnabas again visited this city and “preached the word” (14:25). It stood on the banks of the river Cestrus, some 7 miles from its mouth, and was a place of some commercial importance. It is now a ruin, called Eski Kalessi.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"페르가. 버가(Perga) 소아시아 해안에 있는 팜필리아(Pamphylia)의 수도. 바울과 그의 동료들은 1차 선교 여행 중에 구브로에서 이곳에 상륙했고(행 13:13, 14), 여기서 마가는 일행을 버리고 예루살렘으로 돌아갔다. 얼마 후 바울과 바나바는 다시 이 도시를 방문하여 “말씀을 전”했습니다(14:25). 이곳은 하구에서 약 7마일 떨어진 케스트러스 강 유역에 서 있었고 상업적으로 중요한 장소였습니다. 지금은 Eski Kalessi라고 불리는 폐허가 되었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"a46b4ac8b748cdaa699f01e9cd708abd7ecfe31d253249657bb8d4597bb7011d","source_evidence":{"geographic_types":["river","site"],"scripture_citations_as_printed":["Acts 13:13"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Phrygia","source_key":"PHRYGIA","source_id":"k-PHRYGIA","source_text":"Phrygia. Phrygia\nDry, an irregular and ill-defined district in Asia Minor. It was divided into two parts, the Greater Phrygia on the south, and the Lesser Phrygia on the west. It is the Greater Phrygia that is spoken of in the New Testament. The towns of Antioch in Pisidia (Acts 13:14), Colosse, Hierapolis, Iconium, and Laodicea were situated in it.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"56cbed1f11fd03250bea8d35a1917c89b44be00eb594e12d6ff2f0ea57e64b8c","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Acts 13:14"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Piram","source_key":"PIRAM","source_id":"k-PIRAM","source_text":"Piram. Piram\nLike a wild ass, a king of Jarmuth, a royal city of the Canaanites, who was conquered and put to death by Joshua (10:3, 23, 26).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":false},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"ef019759d59825792c2a1788a0981d6e0f03792a3b1c3808009d817a14b98fc5","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":[],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Rakkath","source_key":"RAKKATH","source_id":"k-RAKKATH","source_text":"Rakkath. Rakkath\nShore-town, a “fenced city” of the tribe of Naphtali (Josh. 19:35). The old name of Tiberias, according to the Rabbins.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"5e86d253b29c8fdc42d99f9c8e556b8276a3c6f15eaf7061752d34284af96cfb","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 19:35"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Ramathaim-zophim","source_key":"RAMATHAIM-ZOPHIM","source_id":"k-RAMATHAIM-ZOPHIM","source_text":"Ramathaim-zophim. Ramathaim-zophim\nThe two heights of the Zophites or of the watchers (only in 1 Sam. 1:1), “in the land of Zuph” (9:5). Ramathaim is another name for Ramah (4).\n\nOne of the Levitical families descended from Kohath, that of Zuph or Zophai (1 Chr. 6:26, 35), had a district assigned to them in Ephraim, which from this circumstance was called “the land of Zuph,” and hence the name of the town, “Zophim.” It was the birth-place of Samuel and the seat of his authority (1 Sam. 2:11; 7:17). It is frequently mentioned in the history of that prophet and of David (15:34; 16:13; 19:18-23). Here Samuel died and was buried (25:1).\n\nThis town has been identified with the modern Neby Samwil (“the prophet Samuel”), about 4 or 5 miles north-west of Jerusalem. But there is no certainty as to its precise locality. Some have supposed that it may be identical with Arimathea of the New Testament. (See MIZPAH).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"라마다임소빔. 라마다임소빔 소피 족속이나 순찰자들의 두 높이(삼상 1:1에만 해당), “숩 땅에”(9:5). 라마다임은 라마(4)의 다른 이름이다. 고핫의 후손인 숩 또는 소배(대상 6:26, 35)의 후손인 레위 가족 중 한 사람은 에브라임에서 그들에게 할당된 지역을 가지고 있었는데, 이 상황에서 “숩 땅”이라고 불렸으므로 그 성읍의 이름은 “소빔”이 되었다. 이곳은 사무엘이 태어난 곳이자 그의 권위가 있었던 곳이다(삼상 2:11; 7:17). 이는 선지자와 다윗의 역사에서 자주 언급됩니다(15:34; 16:13; 19:18-23). 여기서 사무엘은 죽어 장사되었습니다(25:1). 이 도시는 예루살렘에서 북서쪽으로 약 4~5마일 떨어진 현대의 네비 삼윌(“선지자 사무엘”)과 동일시됩니다. 하지만 이에 대한 확실성은 없다. 정확한 지역. 어떤 사람들은 그것이 신약의 아리마대와 동일할 수 있다고 생각했습니다. (미즈파 참조).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"5afda8c86bf703668e6ef71e6efc2ca94205e304b7c37b07e0a79d8e1fff9f9c","source_evidence":{"geographic_types":["region"],"scripture_citations_as_printed":["1 Sam. 1:1","1 Chr. 6:26","1 Sam. 2:11"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Ramath-lehi","source_key":"RAMATH-LEHI","source_id":"k-RAMATH-LEHI","source_text":"Ramath-lehi. Ramath-lehi\nElevation of Lehi, or the jawbone height; i.e., the Ramah of Lehi (Judg. 15:15-17). The phrase “in the jaw,” ver. 19, Authorized Version, is in the margin, also in the Revised Version, “in Lehi.” Here Samson slew a thousand Philistines with a jawbone.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"98c2158eba048ea37cb0b07a79e0cde0c8595ed0c78ba70cb8a8c4070c58e3c9","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Judg. 15:15-17"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Ramath-mizpeh","source_key":"RAMATH-MIZPEH","source_id":"k-RAMATH-MIZPEH","source_text":"Ramath-mizpeh. Ramath-mizpeh\nThe height of Mizpeh or of the watch-tower (Josh. 13:26), a place mentioned as one of the limits of Gad. There were two Mizpehs on the east of the Jordan. This was the Mizpeh where Jacob and Laban made a covenant, “Mizpeh of Gilead,” called also Galeed and Jegar-sahadutha. It has been identified with the modern es-Salt, where the roads from Jericho and from Shechem to Damascus unite, about 25 miles east of the Jordan and 13 south of the Jabbok.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"라맛-미스베. 라맛미스베 미스베 또는 망대(수 13:26)의 높이로서 갓의 경계 중 하나로 언급된 장소. 요단강 동쪽에는 미스바가 두 개 있었습니다. 이곳은 야곱과 라반이 언약을 맺은 곳인 미스바, 곧 갈르엣이라고도 하고 여갈사하두다라고도 하는 “길르앗 미스베”였습니다. 이곳은 여리고와 세겜에서 다마스쿠스까지의 도로가 합쳐지는 현대의 에스살트(es-Salt)와 동일시되는데, 이곳은 요르단에서 동쪽으로 약 25마일, 얍복에서 남쪽으로 13마일 떨어져 있습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"863d6b52107a947dbff85b19c31eb3e653c46b706887e234bf088f3dd621b9c3","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Josh. 13:26"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Rameses","source_key":"RAMESES","source_id":"k-RAMESES","source_text":"Rameses. Rameses\n“the land of” (Gen. 47:11), was probably “the land of Goshen” (q.v.) 45:10. After the Hebrews had built Rameses, one of the “treasure cities,” it came to be known as the “land” in which that city was built.\n\nThe city bearing this name (Ex. 12:37) was probably identical with Zoan, which Rameses II. (“son of the sun”) rebuilt. It became his special residence, and ranked next in importance and magnificance to Thebes. Huge masses of bricks, made of Nile mud, sun-dried, some of them mixed with stubble, possibly moulded by Jewish hands, still mark the site of Rameses. This was the general rendezvous of the Israelites before they began their march out of Egypt. Called also Raamses (Ex. 1:11).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"de910da07fb27d78ca27c77ac940b123ac345e1567a0b9b4ae77ed647d72dd75","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Gen. 47:11","Ex. 12:37","Ex. 1:11"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Rehob","source_key":"REHOB","source_id":"k-REHOB","source_text":"Rehob. Rehob\nStreet; broad place. (1.) The father of Hadadezer, king of Tobah (2 Sam. 8:3, 12).\n\n(2.) Neh. 10:11.\n\n(3.) The same, probably, as Beth-rehob (2 Sam. 10:6, 8; Judg. 18:28), a place in the north of Palestine (Num. 13:21). It is now supposed to be represented by the castle of Hunin, south-west of Dan, on the road from Hamath into Coele-Syria.\n\n(4.) A town of Asher (Josh. 19:28), to the east of Zidon.\n\n(5.) Another town of Asher (Josh. 19:30), kept possession of by the Canaanites (Judg. 1:31).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"르홉. 레홉 스트리트; 넓은 곳. (1) 도바 왕 하닷에셀의 아버지(삼하 8:3, 12). (2.) 네. 10:11. (3) 아마도 팔레스타인 북쪽에 있는 장소인 벳르홉(삼하 10:6, 8; 삿 18:28)과 같은 곳일 것이다(민 13:21). 이제 그것은 하맛에서 코엘레-시리아로 가는 길에 있는 단의 남서쪽에 있는 후닌 성으로 대표되는 것으로 추정됩니다. (4) 시돈 동쪽에 있는 아셀 성읍(수 19:28). (5.) 아셀의 또 다른 성읍(수 19:30)은 가나안 사람들이 소유하고 있었다(삿 1:31).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"08578b4461a1f80c03f2b75285f0eb0eb21342126906617a3efac457c52bd9af","source_evidence":{"geographic_types":["settlement","site"],"scripture_citations_as_printed":["2 Sam. 8:3","Neh. 10:11","2 Sam. 10:6","Judg. 18:28","Num. 13:21","Josh. 19:28","Josh. 19:30","Judg. 1:31"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Rephaim","source_key":"REPHAIM","source_id":"k-REPHAIM","source_text":"Rephaim. Rephaim\nLofty men; giants, (Gen. 14:5; 2 Sam. 21:16, 18, marg. A.V., Rapha, marg. R.V., Raphah; Deut. 3:13, R.V.; A.V., “giants”). The aborigines of Palestine, afterwards conquered and dispossessed by the Canaanite tribes, are classed under this general title. They were known to the Moabites as Emim, i.e., “fearful”, (Deut. 2:11), and to the Ammonites as Zamzummim. Some of them found refuge among the Philistines, and were still existing in the days of David. We know nothing of their origin. They were not necessarily connected with the “giants” (R.V., “Nephilim”) of Gen. 6:4. (See GIANTS.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"d408899fb8c4df1f0384d8812e069a24f7b570aceecdc58e3c383f5946d4bf0f","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Gen. 14:5","2 Sam. 21:16","Deut. 3:13","Deut. 2:11","Gen. 6:4"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Rephidim","source_key":"REPHIDIM","source_id":"k-REPHIDIM","source_text":"Rephidim. Rephidim\nSupports, one of the stations of the Israelites, situated in the Wady Feiran, near its junction with the Wady esh-Sheikh. Here no water could be found for the people to drink, and in their impatience they were ready to stone Moses, as if he were the cause of their distress. At the command of God Moses smote “the rock in Horeb,” and a copious stream flowed forth, enough for all the people. After this the Amalekites attacked the Israelites while they were here encamped, but they were utterly defeated (Ex. 17:1, 8-16). They were the “first of the nations” to make war against Israel (Num. 24:20).\n\nLeaving Rephidim, the Israelites advanced into the wilderness of Sinai (Ex. 19:1, 2; Num. 33:14, 15), marching probably through the two passes of the Wady Solaf and the Wady esh-Sheikh, which converge at the entrance to the plain er-Rahah, the “desert of Sinai,” which is two miles long and about half a mile broad. (See SINAI; MERIBAH.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"80e0cfd4fc1ec8ecc48aaa6585a38c36722a1c0da937883248a10aba2573369b","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Ex. 17:1","Num. 24:20","Ex. 19:1","Num. 33:14"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Rhegium","source_key":"RHEGIUM","source_id":"k-RHEGIUM","source_text":"Rhegium. Rhegium\nBreach, a town in the south of Italy, on the Strait of Messina, at which Paul touched on his way to Rome (Acts 28:13). It is now called Rheggio.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"레기움. 레기움 브리치(Rhegium Breach)는 바울이 로마로 가는 길에 닿았던 이탈리아 남부 메시나 해협에 있는 마을이다(행 28:13). 지금은 레지오(Rheggio)라고 불립니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"3bc27f1b06193961ef64228926907276445c9aaca62bb372858589fbf1765b39","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Acts 28:13"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Rimmon-parez","source_key":"RIMMON-PAREZ","source_id":"k-RIMMON-PAREZ","source_text":"Rimmon-parez. Rimmon-parez\nA pomegranate breach, or Rimmon of the breach, one of the stations of the Israelites in the wilderness (Num. 33:19, 20).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"be6c597cc4f8a00d188c56f1dec0b9ed7c1cfba76556bdf33e656dee26d5211b","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Num. 33:19"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Rogelim","source_key":"ROGELIM","source_id":"k-ROGELIM","source_text":"Rogelim. Rogelim\nFullers, a town of Gilead, the residence of Barzillai the Gileadite (2 Sam. 17:27; 19:31), probably near to Mahanaim.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"Rogelim. 로글림 풀러스(Rogelim Fullers), 길르앗 사람 바르실래의 거주지였던 길르앗 성읍(삼하 17:27; 19:31). 아마도 마하나임 근처에 있었을 것이다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"862b05966f307a52d02cfdd0f00b79f5606bc9974426d94215f5e029ecf0cf50","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["2 Sam. 17:27"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Rosh","source_key":"ROSH","source_id":"k-ROSH","source_text":"Rosh. Rosh\n(Ezek. 38:2, 3; 39:1) is rendered “chief” in the Authorized Version. It is left untranslated as a proper name in the Revised Version. Some have supposed that the Russians are here meant, as one of the three Scythian tribes of whom Magog was the prince. They invaded the land of Judah in the days of Josiah. Herodotus, the Greek historian, says: “For twenty-eight years the Scythians ruled over Asia, and things were turned upside down by their violence and contempt.” (See BETHSHEAN.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"2c2ad6e7de37017d66a76ba7fe254ae3180a41ed4b7980895ad2925074c2bdf0","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Ezek. 38:2"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Salcah","source_key":"SALCAH","source_id":"k-SALCAH","source_text":"Salcah. Salcah\nWandering, a city of Bashan assigned to the half tribe of Manasseh (Deut. 3:10; Josh. 12:5; 13:11), identified with Salkhad, about 56 miles east of Jordan.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"살카. 살가 방랑(Salcah Wandering)은 므낫세 반 지파에 할당된 바산의 도시(신 3:10; 수 12:5; 13:11)로, 요르단에서 동쪽으로 약 56마일 떨어진 살카드와 동일시된다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"2aaf13a701a21eff1322814afc79a621c3545af756b984173456a64ede32a080","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Deut. 3:10","Josh. 12:5"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Salem","source_key":"SALEM","source_id":"k-SALEM","source_text":"Salem. Salem\nPeace, commonly supposed to be another name of Jerusalem (Gen. 14:18; Ps. 76:2; Heb. 7:1, 2).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"aa932cf02a181fcccd1330ed35f48ce60fd5fb731bb01716fd8332c81bbc979f","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Gen. 14:18","Ps. 76:2"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Salim","source_key":"SALIM","source_id":"k-SALIM","source_text":"Salim. Salim\nPeaceful, a place near AEnon (q.v.), on the west of Jordan, where John baptized (John 3:23). It was probably the Shalem mentioned in Gen. 33:18, about 7 miles south of AEnon, at the head of the great Wady Far’ah, which formed the northern boundary of Judea in the Jordan valley.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"살림. 평화로운 살림(Salim Peaceful), 요한이 세례를 주었던 요르단 서쪽 에논(q.v.) 근처의 장소(요한복음 3:23). 그것은 아마도 창 33:18에 언급된 샬렘, 에논에서 남쪽으로 약 7마일 떨어진 곳, 요르단 계곡에서 유대의 북쪽 경계를 형성하는 거대한 와디 파라(Wady Far'ah)의 머리에 있는 곳이었을 것이다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"9df0389c3262f276e65ffc16433e2b114367aa57a3c8d36ab4cf43d012285c86","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["John 3:23","Gen. 33:18"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Samothracia","source_key":"SAMOTHRACIA","source_id":"k-SAMOTHRACIA","source_text":"Samothracia. Samothracia\nAn island in the AEgean Sea, off the coast of Thracia, about 32 miles distant. This Thracian Samos was passed by Paul on his voyage from Troas to Neapolis (Acts 16:11) on his first missionary journey. It is about 8 miles long and 6 miles broad. Its modern name is Samothraki.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"사모트라키아. 사모트라키아(Samothracia) 트라키아 해안에서 떨어진 에게해에 있는 섬으로 약 32마일 떨어져 있습니다. 이 트라키아 사모스는 바울이 1차 선교 여행 중 트로아스에서 네아폴리스로 항해하는 동안(행 16:11) 지나갔습니다. 길이는 약 8마일, 너비는 6마일이다. 현대 이름은 Samothraki입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"98ea9e804b661ae470db5ccdb3b953b889337a07df22fa30ec7460f0517b4a50","source_evidence":{"geographic_types":["region"],"scripture_citations_as_printed":["Acts 16:11"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Secacah","source_key":"SECACAH","source_id":"k-SECACAH","source_text":"Secacah. Secacah\nEnclosure, one of the six cities in the wilderness of Judah, noted for its “great cistern” (Josh. 15:61). It has been identified with the ruin Sikkeh, east of Bethany.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"6dedf7c9b120d08012d58594ad922748df56d49008ef6a80110a521c329a1741","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 15:61"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Sela","source_key":"SELA","source_id":"k-SELA","source_text":"Sela. Sela\n=Se’lah, rock, the capital of Edom, situated in the great valley extending from the Dead Sea to the Red Sea (2 Kings 14:7). It was near Mount Hor, close by the desert of Zin. It is called “the rock” (Judg. 1:36). When Amaziah took it he called it Joktheel (q.v.) It is mentioned by the prophets (Isa. 16:1; Obad. 1:3) as doomed to destruction.\n\nIt appears in later history and in the Vulgate Version under the name of Petra. “The caravans from all ages, from the interior of Arabia and from the Gulf of Persia, from Hadramaut on the ocean, and even from Sabea or Yemen, appear to have pointed to Petra as a common centre; and from Petra the tide seems again to have branched out in every direction, to Egypt, Palestine, and Syria, through Arsinoe, Gaza, Tyre, Jerusalem, and Damascus, and by other routes, terminating at the Mediterranean.” (See EDOM [2].)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"00c3fd1f3833bbb72f291947d3ab60d98d3df9e01dbed448106b187159f829ca","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["2 Kings 14:7","Judg. 1:36","Isa. 16:1"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Seleucia","source_key":"SELEUCIA","source_id":"k-SELEUCIA","source_text":"Seleucia. Seleucia\nThe sea-port of Antioch, near the mouth of the Orontes. Paul and his companions sailed from this port on their first missionary journey (Acts 13:4). This city was built by Seleucus Nicator, the “king of Syria.” It is said of him that “few princes have ever lived with so great a passion for the building of cities. He is reputed to have built in all nine Seleucias, sixteen Antiochs, and six Laodiceas.” Seleucia became a city of great importance, and was made a “free city” by Pompey. It is now a small village, called el-Kalusi.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"셀루키아. 셀레우키아(Seleucia) 오론테스 강 어귀 근처에 있는 안티오크의 항구. 바울과 그의 동료들은 1차 전도여행에서 이 항구를 떠나 배를 탔다(행 13:4). 이 도시는 “시리아 왕” 셀레우코스 니카토르에 의해 건설되었습니다. 그에 대해 \"도시 건설에 그토록 큰 열정을 갖고 살았던 군주는 거의 없었습니다. 그는 셀루키아 9개, 안디옥 16개, 라오디게아 6개를 모두 건설한 것으로 알려져 있습니다.\" 셀레우키아는 매우 중요한 도시가 되었고, 폼페이우스에 의해 “자유 도시”가 되었습니다. 지금은 엘 칼루시(el-Kalusi)라고 불리는 작은 마을입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"c2637ba0bbda9b79f288d02bf170ad05ededd9b3143c42006766c09b1521d8d5","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Acts 13:4"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Shebarim","source_key":"SHEBARIM","source_id":"k-SHEBARIM","source_text":"Shebarim. Shebarim\nBreaks; ruins, a place near Ai (Josh. 7:5; R.V. marg., “the quarries”).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"셰바림. 셰바림 브레이크; 폐허, 아이 근처의 장소(수 7:5; R.V. marg., “채석장”).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"2f6bf9c20348363ee8bf95645fccd3faa75f196d18e64742852dbe5a51e4ec75","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Josh. 7:5"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Shihor","source_key":"SHIHOR","source_id":"k-SHIHOR","source_text":"Shihor. Shihor\nDark, (1 Chr. 13:5), the southwestern boundary of Canaan, the Wady el-‘Arish. (See SIHOR; NILE.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"4d37a321ccc9a597eb119932a5575c22c8bb25533186e8569f891ac2856606fb","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["1 Chr. 13:5"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Shilhim","source_key":"SHILHIM","source_id":"k-SHILHIM","source_text":"Shilhim. Shilhim\nAqueducts, a town in the south of Judah (Josh. 15:32); called also Sharuhen and Shaaraim (19:6).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"실힘. 유다 남쪽에 있는 성읍 실힘 수로(수 15:32); 사루헨과 사아라임이라고도 불린다(19:6).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"7235e0fbd85ac76b8771243b95acd4bca9ac9cda1ae3aade0b3a2f23617d4218","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:32"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Shimron","source_key":"SHIMRON","source_id":"k-SHIMRON","source_text":"Shimron. Shimron\nWatch-post, an ancient city of the Canaanites; with its villages, allotted to Zebulun (Josh. 19:15); now probably Semunieh, on the northern edge of the plain of Esdraelon, 5 miles west of Nazareth.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"d877facdb60361cfe64e75e7ae99501ebcb53bf04dbac274cfb5211057b2083c","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 19:15"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Shimron-meron","source_key":"SHIMRON-MERON","source_id":"k-SHIMRON-MERON","source_text":"Shimron-meron. Shimron-meron\nThe same, probably, as Shimron (Josh. 12:20).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"cb1fdf756d2a1c177195b12b92ff9d04910505bbac30944ad1b36d53d1699380","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 12:20"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Shittim","source_key":"SHITTIM","source_id":"k-SHITTIM","source_text":"Shittim. Shittim\nAcacias, also called “Abel-shittim” (Num. 33:49), a plain or valley in the land of Moab where the Israelites were encamped after their two victories over Sihon and Og, at the close of their desert wanderings, and from which Joshua sent forth two spies (q.v.) “secretly” to “view” the land and Jericho (Josh. 2:1).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"쉿. “아벨싯딤”이라고도 불리는 싯딤 아카시아(민 33:49). 이스라엘 백성이 시혼과 옥을 상대로 두 차례 승리를 거둔 후, 광야 방랑이 끝날 무렵에 진을 쳤던 모압 땅에 있는 평야 또는 계곡. 여호수아는 그곳에서 그 땅과 여리고를 “살펴보기” 위해 두 명의 정탐꾼(qv)을 “은밀히” 보냈습니다(수 2:1).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"6e4eaa9215fbfd0801462fb3785487c5be0b9053a3a71c774dde057d7a8f90d4","source_evidence":{"geographic_types":["region"],"scripture_citations_as_printed":["Num. 33:49","Josh. 2:1"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Sibmah","source_key":"SIBMAH","source_id":"k-SIBMAH","source_text":"Sibmah. Sibmah\nCoolness; fragrance, a town in Reuben, in the territory of Moab, on the east of Jordan (Josh. 13:19); called also Shebam and Shibmah (Num. 32:3, 38). It was famous for its vines (Isa. 16:9; Jer. 48:32). It has been identified with the ruin of Sumieh, where there are rock-cut wine-presses. This fact explains the words of the prophets referred to above. It was about 5 miles east of Heshbon.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"십마. 십마 쿨니스; 향수(Fragrance), 요단 동편 모압 지역 르우벤에 있는 성읍(수 13:19); 스밤과 십마라고도 불린다(민 32:3, 38). 이곳은 포도나무로 유명했습니다(사 16:9; 렘 48:32). 이곳은 암석을 깎아 만든 포도주 압착기가 있는 수미에(Sumieh)의 폐허와 동일시되었습니다. 이 사실은 위에 언급된 선지자들의 말을 설명합니다. 그곳은 헤스본에서 동쪽으로 약 5마일 떨어진 곳이었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"6e3d1c89f0af26eb1a32739509503600a8665b31b6348ee40e9b2b277dc80d71","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 13:19","Num. 32:3","Isa. 16:9","Jer. 48:32"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Sin","source_key":"SIN","source_id":"k-SIN","source_text":"Sin. Sin\nIs “any want of conformity unto or transgression of the law of God” (1 John 3:4; Rom. 4:15), in the inward state and habit of the soul, as well as in the outward conduct of the life, whether by omission or commission (Rom. 6:12-17; 7:5-24). It is “not a mere violation of the law of our constitution, nor of the system of things, but an offence against a personal lawgiver and moral governor who vindicates his law with penalties. The soul that sins is always conscious that his sin is (1) intrinsically vile and polluting, and (2) that it justly deserves punishment, and calls down the righteous wrath of God. Hence sin carries with it two inalienable characters, (1) ill-desert, guilt (reatus); and (2) pollution (macula).”, Hodge’s Outlines.\n\nThe moral character of a man’s actions is determined by the moral state of his heart. The disposition to sin, or the habit of the soul that leads to the sinful act, is itself also sin (Rom. 6:12-17; Gal. 5:17; James 1:14, 15).\n\nThe origin of sin is a mystery, and must for ever remain such to us. It is plain that for some reason God has permitted sin to enter this world, and that is all we know. His permitting it, however, in no way makes God the author of sin.\n\nAdam’s sin (Gen. 3:1-6) consisted in his yielding to the assaults of temptation and eating the forbidden fruit. It involved in it, (1) the sin of unbelief, virtually making God a liar; and (2) the guilt of disobedience to a positive command. By this sin he became an apostate from God, a rebel in arms against his Creator. He lost the favour of God and communion with him; his whole nature became depraved, and he incurred the penalty involved in the covenant of works.\n\nOriginal sin. “Our first parents being the root of all mankind, the guilt of their sin was imputed, and the same death in sin and corrupted nature were conveyed to all their posterity, descending from them by ordinary generation.” Adam was constituted by God the federal head and representative of all his posterity, as he was also their natural head, and therefore when he fell they fell with him (Rom. 5:12-21; 1 Cor. 15:22-45). His probation was their probation, and his fall their fall. Because of Adam’s first sin all his posterity came into the world in a state of sin and condemnation, i.e., (1) a state of moral corruption, and (2) of guilt, as having judicially imputed to them the guilt of Adam’s first sin.\n\n“Original sin” is frequently and properly used to denote only the moral corruption of their whole nature inherited by all men from Adam. This inherited moral corruption consists in, (1) the loss of original righteousness; and (2) the presence of a constant proneness to evil, which is the root and origin of all actual sin. It is called “sin” (Rom. 6:12, 14, 17; 7:5-17), the “flesh” (Gal. 5:17, 24), “lust” (James 1:14, 15), the “body of sin” (Rom. 6:6), “ignorance,” “blindness of heart,” “alienation from the life of God” (Eph. 4:18, 19). It influences and depraves the whole man, and its tendency is still downward to deeper and deeper corruption, there remaining no recuperative element in the soul. It is a total depravity, and it is also universally inherited by all the natural descendants of Adam (Rom. 3:10-23; 5:12-21; 8:7). Pelagians deny original sin, and regard man as by nature morally and spiritually well; semi-Pelagians regard him as morally sick; Augustinians, or, as they are also called, Calvinists, regard man as described above, spiritually dead (Eph. 2:1; 1 John 3:14).\n\nThe doctrine of original sin is proved, (1.) From the fact of the universal sinfulness of men. “There is no man that sinneth not” (1 Kings 8:46; Isa. 53:6; Ps. 130:3; Rom. 3:19, 22, 23; Gal. 3:22). (2.) From the total depravity of man. All men are declared to be destitute of any principle of spiritual life; man’s apostasy from God is total and complete (Job 15:14-16; Gen. 6:5,6). (3.) From its early manifestation (Ps. 58:3; Prov. 22:15). (4.) It is proved also from the necessity, absolutely and universally, of regeneration (John 3:3; 2 Cor. 5:17). (5.) From the universality of death (Rom. 5:12-20).\n\nVarious kinds of sin are mentioned, (1.) “Presumptuous sins,” or as literally rendered, “sins with an uplifted hand”, i.e., defiant acts of sin, in contrast with “errors” or “inadvertencies” (Ps. 19:13). (2.) “Secret”, i.e., hidden sins (19:12); sins which escape the notice of the soul. (3.) “Sin against the Holy Ghost” (q.v.), or a “sin unto death” (Matt. 12:31, 32; 1 John 5:16), which amounts to a wilful rejection of grace.\n\nSin, a city in Egypt, called by the Greeks Pelusium, which means, as does also the Hebrew name, “clayey” or “muddy,” so called from the abundance of clay found there. It is called by Ezekel (Ezek. 30:15) “the strength of Egypt, “thus denoting its importance as a fortified city. It has been identified with the modern Tineh, “a miry place,” where its ruins are to be found. Of its boasted magnificence only four red granite columns remain, and some few fragments of others.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"d1e083f1d51efdeae8cb7a7fab0679e704d59a4a9e07524278019cfb60d8b8f0","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["1 John 3:4","Rom. 4:15","Rom. 6:12-17","Rom. 6:12-17","Gen. 3:1-6","Rom. 5:12-21","Rom. 6:12","Rom. 6:6"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Sorek","source_key":"SOREK","source_id":"k-SOREK","source_text":"Sorek. Sorek\nChoice vine, the name of a valley, i.e., a torrent-bed, now the Wady Surar, “valley of the fertile spot,” which drains the western Judean hills, and flowing by Makkedah and Jabneel, falls into the sea some eight miles south of Joppa. This was the home of Deliah, whom Samson loved (Judg. 16:4).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"소렉. 계곡의 이름인 소렉 초이스(Sorek Choice) 포도나무, 즉 급류 바닥, 현재는 와디 수라(Wady Surar, \"비옥한 곳의 계곡\")는 유대 서쪽 언덕에서 배수되고 막게다와 얍느엘을 거쳐 흘러 요파에서 남쪽으로 약 8마일 떨어진 바다에 빠집니다. 이곳은 삼손이 사랑한 들랴의 집이었습니다(삿 16:4).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"caa16f578a6ac6b16b32eadf3cb4dd02acda02f84bac7a24970ab2074f8ac86c","source_evidence":{"geographic_types":["river","site"],"scripture_citations_as_printed":["Judg. 16:4"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Suph","source_key":"SUPH","source_id":"k-SUPH","source_text":"Suph. Suph\n(Deut. 1:1, R.V.; marg., “some ancient versions have the Red Sea,” as in the A.V.). Some identify it with Suphah (Num. 21:14, marg., A.V.) as probably the name of a place. Others identify it with es-Sufah = Maaleh-acrabbim (Josh. 15:3), and others again with Zuph (1 Sam. 9:5). It is most probable, however, that, in accordance with the ancient versions, this word is to be regarded as simply an abbreviation of Yam-suph, i.e., the “Red Sea.”","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"수프. 수프(신명기 1:1, R.V.; marg., A.V.에서와 같이 “어떤 고대 역본에는 홍해가 있다”). 어떤 사람들은 아마도 그곳의 이름을 수바(민 21:14, marg., A.V.)와 동일시합니다. 다른 사람들은 그것을 es-Sufah = Maaleh-acrabbim(수 15:3)으로 식별하고 다른 사람들은 다시 Zuph(삼상 9:5)로 식별합니다. 그러나 고대 번역에 따르면 이 단어는 단순히 얌수프, 즉 “홍해”의 약어로 간주되어야 할 가능성이 가장 높습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"295431a2ac1695ec75c1cb7bbef78e9b39aa1bd30f5dc66b0f5eb670c153a22f","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Deut. 1:1","Num. 21:14","Josh. 15:3","1 Sam. 9:5"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Taberah","source_key":"TABERAH","source_id":"k-TABERAH","source_text":"Taberah. Taberah\nBurning, a place in the wilderness of Paran, where the “fire of the Lord” consumed the murmuring Israelites (Num. 11:3; Deut. 9:22). It was also called Kibroth-hattaavah (q.v.).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"다베라. 다베라 불태운 곳, 바란 광야에 있는 곳으로, “여호와의 불”이 불평하는 이스라엘 백성들을 태웠던 곳입니다(민 11:3; 신 9:22). 그것은 또한 기브롯 핫다아와(q.v.)라고도 불렸다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"c31ddd2c29bf056f875354304c877b25383aaddd6a57c71efc5057132bf74706","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Num. 11:3","Deut. 9:22"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Taanach","source_key":"TAANACH","source_id":"k-TAANACH","source_text":"Taanach. Taanach\nA sandy place, an ancient royal city of the Canaanites, on the south-western border of the plain of Esdraelon, 4 miles south of Megiddo. Its king was conquered by Joshua (12:21). It was assigned to the Levites of the family of Kohath (17:11-18; 21:25). It is mentioned in the song of Deborah (Judg. 5:19). It is identified with the small modern village of Ta’annuk.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"43c76b83168e9f46526f7405ee902d204701e736c7ff87bc7a764a75840c9053","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Judg. 5:19"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Tahapanes","source_key":"TAHAPANES","source_id":"k-TAHAPANES","source_text":"Tahapanes. Tahapanes\n=Tahpanhes=Tehaphnehes, (called “Daphne” by the Greeks, now Tell Defenneh), an ancient Egyptian city, on the Tanitic branch of the Nile, about 16 miles from Pelusium. The Jews from Jerusalem fled to this place after the death of Gedaliah (q.v.), and settled there for a time (Jer. 2:16; 43:7; 44:1; 46:14). A platform of brick-work, which there is every reason to believe was the pavement at the entry of Pharaoh’s palace, has been discovered at this place. “Here,” says the discoverer, Mr. Petrie, “the ceremony described by Jeremiah [43:8-10; “brick-kiln”, i.e., pavement of brick] took place before the chiefs of the fugitives assembled on the platform, and here Nebuchadnezzar spread his royal pavilion” (R.V., “brickwork”).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"9c2f60fba66e5354594d48444bf421a1a9f9bfd10579a85a2d627cf0a33a5b37","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Jer. 2:16"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Tappuah","source_key":"TAPPUAH","source_id":"k-TAPPUAH","source_text":"Tappuah. Tappuah\nApple-region. (1.) A town in the valley or lowland of Judah; formerly a royal city of the Canaanites (Josh. 12:17; 15:34). It is now called Tuffuh, about 12 miles west of Jerusalem.\n\n(2.) A town on the border of Ephraim (Josh. 16:8). The “land” of Tappuah fell to Manasseh, but the “city” to Ephraim (17:8).\n\n(3.) En-tappuah, the well of the apple, probably one of the springs near Yassuf (Josh. 17:7).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"타푸아. Tappuah Apple 지역. (1) 유다의 골짜기나 저지대에 있는 성읍. 이전에는 가나안 사람들의 왕도였다(수 12:17; 15:34). 지금은 예루살렘에서 서쪽으로 약 19km 떨어진 곳에 투푸(Tuffuh)라고 불립니다. (2) 에브라임 변경에 있는 성읍(수 16:8). 답부아의 “땅”은 므낫세에게 떨어졌으나 “성”은 에브라임에게 떨어졌다(17:8). (3) 엔답부아(En-tappuah), 사과의 우물, 아마도 야수프(Yassuf) 근처의 샘 중 하나일 것이다(수 17:7).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"3d52e5187751fb4c892dd6dc9f096684182ac54b71652f5e3399ac7639688bac","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 12:17","Josh. 16:8","Josh. 17:7"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Tophet","source_key":"TOPHET","source_id":"k-TOPHET","source_text":"Tophet. Tophet\n=Topheth, from Heb. toph “a drum,” because the cries of children here sacrificed by the priests of Moloch were drowned by the noise of such an instrument; or from taph or toph, meaning “to burn,” and hence a place of burning, the name of a particular part in the valley of Hinnom. “Fire being the most destructive of all elements, is chosen by the sacred writers to symbolize the agency by which God punishes or destroys the wicked. We are not to assume from prophetical figures that material fire is the precise agent to be used. It was not the agency employed in the destruction of Sennacherib, mentioned in Isa. 30:33...Tophet properly begins where the Vale of Hinnom bends round to the east, having the cliffs of Zion on the north, and the Hill of Evil Counsel on the south. It terminates at Beer ‘Ayub, where it joins the Valley of Jehoshaphat. The cliffs on the southern side especially abound in ancient tombs. Here the dead carcasses of beasts and every offal and abomination were cast, and left to be either devoured by that worm that never died or consumed by that fire that was never quenched.” Thus Tophet came to represent the place of punishment. (See HINNOM.)","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"토펫. 토벳 = 도벳, 히브리어. “북”을 토프. 왜냐하면 이곳에서 몰록의 제사장들이 제물로 바친 아이들의 울음소리가 그러한 악기의 소음에 묻혀버렸기 때문이다. 또는 “불타다”를 뜻하는 타프나 톱에서 유래하여 불타는 장소, 즉 힌놈 골짜기의 특정 부분을 가리키는 이름. \"모든 요소 중에서 가장 파괴적인 불은 하나님께서 악인을 벌하시거나 멸망시키는 수단을 상징하기 위해 신성한 작가들에 의해 선택되었습니다. 우리는 예언적 인물로부터 물질적인 불이 사용되는 정확한 수단이라고 가정해서는 안 됩니다. 그것은 이사야 30:33에 언급된 산헤립의 멸망에 사용된 수단이 아니었습니다....토벳은 힌놈 골짜기가 동쪽으로 구부러져 북쪽에 시온의 절벽이 있고, 성의 언덕이 있는 곳에서 적절하게 시작됩니다. 남쪽의 사악한 조언. 브엘아유브에서 끝나고 여호사밧 골짜기와 합류한다. 특히 남쪽 절벽에는 고대 무덤이 많이 있습니다. 여기에는 죽은 짐승의 시체와 모든 내장과 가증한 것이 던져져 결코 죽지 아니하는 벌레에게 먹히거나 결코 꺼지지 않는 불에 소멸되도록 버려졌느니라.” 그리하여 도벳은 형벌의 장소를 상징하게 되었다. (힌놈 참조)","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"4ec1e0de81c1390e9e3bc7ba4ca510e3864431fcd1936abaa339aa217f3a99e8","source_evidence":{"geographic_types":["site"],"scripture_citations_as_printed":["Isa. 30:33"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Ulai","source_key":"ULAI","source_id":"k-ULAI","source_text":"Ulai. Ulai\nThe Eulaus of the Greeks; a river of Susiana. It was probably the eastern branch of the Choasper (Kerkhan), which divided into two branches some 20 miles above the city of Susa. Hence Daniel (8:2,16) speaks of standing “between the banks of Ulai”, i.e., between the two streams of the divided river.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":false},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"673647b43d4a17404c8f1c0337b859a609053ca098ddf687de3ad39183146fb6","source_evidence":{"geographic_types":["river"],"scripture_citations_as_printed":[],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Uzal","source_key":"UZAL","source_id":"k-UZAL","source_text":"Uzal. Uzal\nA wanderer, a descendant of Joktan (Gen. 10:27; 1 Chr. 1:21), the founder apparently of one of the Arab tribes; the name also probably of the province they occupied and of their chief city.","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"d920a86f14c2b20313371a63b7baeed019ff0168d890e6bcf03f7074ff63dd79","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Gen. 10:27","1 Chr. 1:21"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Zaanan","source_key":"ZAANAN","source_id":"k-ZAANAN","source_text":"Zaanan. Zaanan\nPlace of flocks, mentioned only in Micah 1:11. It may be identified with Zenan, in the plain country of Judah (Josh. 15:37).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"a2198a55e1f7d45c008d1366eadd24882be0561422faa661e8f97f7ec253d3ad","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Josh. 15:37"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Zalmon","source_key":"ZALMON","source_id":"k-ZALMON","source_text":"Zalmon. Zalmon\nShady. (1.) One of David’s warriors, called the Ahohite (2 Sam. 23:28); called also Ilai (1 Chr. 11:29).\n\n(2.) A wood near Shechem, from which Abimelech and his party brought boughs and “put them to the hold” of Shechem, “and set the hold on fire” (Judg. 9:48). Probably the southern peak of Gerizim, now called Jebel Sulman. (See SALMON.)","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"83fc6f1d1b61178937ff0d991a67071234e8f1f70a7e1f5a63c6b5764c0072e8","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["2 Sam. 23:28","1 Chr. 11:29","Judg. 9:48"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Zanoah","source_key":"ZANOAH","source_id":"k-ZANOAH","source_text":"Zanoah. Zanoah\nMarsh. (1.) A town in the low country or shephelah of Judah, near Zorah (Josh. 15:34). It was re-occupied after the return from the Captivity (Neh. 11:30). Zanu’ah in Wady Ismail, 10 miles west of Jerusalem, occupies probably the same site.\n\n(2.) A town in the hill country of Judah, some 10 miles to the south-west of Hebron (Josh. 15:56).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"자노아. 자노아 마쉬. (1) 소라 근처 유다의 저지대 또는 셰펠라에 있는 성읍(수 15:34). 포로 생활에서 돌아온 후 다시 이곳에 거주하게 되었습니다(느 11:30). 예루살렘에서 서쪽으로 10마일 떨어진 와디 이스마일(Wady Ismail)에 있는 자누아(Zanu'ah)도 아마도 같은 장소를 차지하고 있을 것입니다. (2) 헤브론 남서쪽으로 약 10마일 떨어진 유다 산간지대에 있는 한 성읍(수 15:56).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"9276b6927475b6900f290aa572988b7fbbee83a1e4ef6f35263675008b2efce4","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:34","Neh. 11:30","Josh. 15:56"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Zareth-shahar","source_key":"ZARETH-SHAHAR","source_id":"k-ZARETH-SHAHAR","source_text":"Zareth-shahar. Zareth-shahar\nThe splendour of the dawn, a city “in the mount of the valley” (Josh. 13:19). It is identified with the ruins of Zara, near the mouth of the Wady Zerka Main, on the eastern shore of the Dead Sea, some 3 miles south of the Callirrhoe. Of this town but little remains. “A few broken basaltic columns and pieces of wall about 200 yards back from the shore, and a ruined fort rather nearer the sea, about the middle of the coast line of the plain, are all that are left” (Tristram’s Land of Moab).","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"자렛 샤하르. 사르렛샤하르 새벽의 영광, “골짜기 산에 있는” 성읍(수 13:19). 그것은 Callirrhoe에서 남쪽으로 약 3마일 떨어진 사해 동쪽 해안에 있는 Wady Zerka Main 입구 근처에 있는 Zara의 유적과 동일시됩니다. 이 마을에는 거의 남아 있지 않습니다. \"해안에서 약 200야드 떨어진 곳에 부서진 현무암 기둥 몇 개와 성벽 조각, 바다에 더 가까운 평야 해안선 중앙쯤에 폐허가 된 요새만이 남아 있는 전부입니다\"(Tristram의 모압 땅).","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"f0fd0250603cd950ab85f3acaaa7d20437a7cbcd405bc80fd820aeb978d5e6e3","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 13:19"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Zedad","source_key":"ZEDAD","source_id":"k-ZEDAD","source_text":"Zedad. Zedad\nSide; sloping place, a town in the north of Palestine, near Hamath (Num. 34:8; Ezek. 47:15). It has been identified with the ruins of Sudud, between Emesa (Hums) and Baalbec, but that is uncertain.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"제다드. 제다드사이드; 경사지, 팔레스타인 북쪽 하맛 근처에 있는 성읍(민 34:8; 겔 47:15). 그것은 Emesa(Hums)와 Baalbec 사이에 있는 Sudud의 폐허와 동일시되었지만 확실하지 않습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"351c84aa1bb30d83dadaa457bdd1a5061e7091c1ea2f0be2208d539aa51d07ba","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Num. 34:8","Ezek. 47:15"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Zelah","source_key":"ZELAH","source_id":"k-ZELAH","source_text":"Zelah. Zelah\nSlope; side, a town in Benjamin, where Saul and his son Jonathan were buried (2 Sam. 21:14). It was probably Saul’s birthplace.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"젤라. 젤라 슬로프; 사울과 그의 아들 요나단이 묻힌 베냐민 지방의 한 성읍(삼하 21:14). 아마도 그곳은 사울의 출생지였을 것입니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"baf1f81b05518672978d9e4fff24b758ff5570fa973e5bd7acccdb99d951e40e","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["2 Sam. 21:14"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Zemaraim","source_key":"ZEMARAIM","source_id":"k-ZEMARAIM","source_text":"Zemaraim. Zemaraim\n(1.) A town of Benjamin (Josh. 18:22); now the ruin, rather two ruins, es-Sumrah, 4 miles north of Jericho.\n\n(2.) A mount in the highlands of Ephraim, to the north of Jerusalem (2 Chr. 13:4-20). Here the armies of Abijah and Jeroboam engaged in a bloody battle, which issued in the total defeat of the king of Israel, who never “recovered strength again,” and soon after died.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"제마라임. 스마라임 (1.) 베냐민의 성읍(수 18:22); 이제 폐허는 여리고에서 북쪽으로 4마일 떨어진 에스숨라(es-Sumrah)라는 두 폐허입니다. (2) 예루살렘 북쪽, 에브라임 고지대에 있는 산(대하 13:4-20). 여기서 아비야와 여로보암의 군대는 피비린내 나는 전투를 벌였고, 그 결과 “다시는 힘을 회복하지” 못한 이스라엘 왕은 완전히 패배하고 곧 죽었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"30178820aec9261eacefecdd608e7f4e2758db9213d60e18b1f78b166ccdad17","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 18:22","2 Chr. 13:4-20"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Zered","source_key":"ZERED","source_id":"k-ZERED","source_text":"Zered. Zered\n=Zared, luxuriance; willow bush, a brook or valley communicating with the Dead Sea near its southern extremity (Num. 21:12; Deut. 2:14). It is called the “brook of the willows” (Isa. 15:7) and the “river of the wilderness” (Amos 6:14). It has been identified with the Wady el-Aksy.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"제레드. Zered =Zared, 사치; 버드나무 숲, 남쪽 끝 근처에서 사해와 연결되는 시냇물이나 계곡(민 21:12; 신 2:14). 그것은 “버드나무 시내”(사 15:7), “광야의 강”(암 6:14)으로 불린다. Wady el-Aksy로 확인되었습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"537aa3aba5027845e663002b39b93b05718afa4b711bed9527d0282cc4d92838","source_evidence":{"geographic_types":["river"],"scripture_citations_as_printed":["Num. 21:12","Deut. 2:14","Isa. 15:7","Amos 6:14"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Zin","source_key":"ZIN","source_id":"k-ZIN","source_text":"Zin. Zin\nA low palm-tree, the south-eastern corner of the desert et-Tih, the wilderness of Paran, between the Gulf of Akabah and the head of the Wady Guraiyeh (Num. 13:21). To be distinguished from the wilderness of Sin (q.v.).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"716db06173cc5a2c8ab5f1c4d889a5c40543192c72c2a2236e9d58c7c33fa231","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["Num. 13:21"],"review_status":"MANUAL_REVIEW_REQUIRED"}},{"name_en":"Zior","source_key":"ZIOR","source_id":"k-ZIOR","source_text":"Zior. Zior\nLittleness, a city in the mountains of Judah (Josh. 15:54); the modern Si’air, 4 1/2 miles north-north-east of Hebron.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"지오르. 유다 산지에 있는 도시 Zior Littleness(수 15:54); 헤브론에서 북북동쪽으로 4 1/2 마일 떨어진 현대 Si'air.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"1f60686c43e894bee13d966eade49c88e913b4dad5f246e4e0a880c9467e2867","source_evidence":{"geographic_types":["settlement"],"scripture_citations_as_printed":["Josh. 15:54"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Zorah","source_key":"ZORAH","source_id":"k-ZORAH","source_text":"Zorah. Zorah\nPlace of wasps, a town in the low country of Judah, afterwards given to Dan (Josh. 19:41; Judg. 18:2), probably the same as Zoreah (Josh. 15:33). This was Samson’s birthplace (Judg. 13:2, 25), and near it he found a grave (16:31). It was situated on the crest of a hill overlooking the valley of Sorek, and was fortified by Rehoboam (2 Chr. 11:10). It has been identified with Sur’ah, in the Wady Surar, 8 miles west of Jerusalem. It is noticed on monuments in the fifteenth century B.C. as attacked by the Abiri or Hebrews.","status":"UNVERIFIED_GEO_CANDIDATE","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":true,"scripture_reference_hint":true},"ko":"조라. 소라 유다 저지대에 있는 말벌의 성읍으로 나중에 단에게 주어졌는데(수 19:41; 삿 18:2), 아마도 소레아(수 15:33)와 같은 곳일 것이다. 이곳은 삼손의 출생지였으며(삿 13:2, 25), 그 근처에서 그는 무덤을 발견했다(16:31). 그것은 소렉 골짜기가 내려다보이는 언덕 꼭대기에 위치해 있었고 르호보암에 의해 요새화되었다(대하 11:10). 그것은 예루살렘에서 서쪽으로 8마일 떨어진 Wady Surar에 있는 Sur'ah와 동일시되었습니다. 이는 기원전 15세기의 기념물에서 볼 수 있습니다. Abiri 또는 히브리인의 공격을 받았습니다.","translation_status":"MT_REFERENCE_ONLY_UNREVIEWED","source_sha256":"6f4e54e9bc74a7237cd900f69d62f1c14d378577b2c677beac63d6f6cfd4059f","source_evidence":{"geographic_types":["settlement","mountain"],"scripture_citations_as_printed":["Josh. 19:41","Judg. 18:2","Josh. 15:33","Judg. 13:2","2 Chr. 11:10"],"review_status":"SOURCE_EVIDENCE_EXTRACTED_IDENTITY_NOT_VERIFIED"}},{"name_en":"Zuph","source_key":"ZUPH","source_id":"k-ZUPH","source_text":"Zuph. Zuph\nHoneycomb, a Kohathite Levite, ancestor of Elkanah and Samuel (1 Sam. 1:1); called also Zophai (1 Chr. 6:26).","status":"TERM_NEEDS_MANUAL_GEO_REVIEW","tier_candidate":"UNASSIGNED","discovery_evidence":{"geographical_wording":false,"scripture_reference_hint":true},"ko":"","translation_status":"GEO_REVIEW_REQUIRED","source_sha256":"0b15c0db21193791ea131e89201782edacc3a2d576a679e8e818cad7cf81e480","source_evidence":{"geographic_types":[],"scripture_citations_as_printed":["1 Sam. 1:1","1 Chr. 6:26"],"review_status":"MANUAL_REVIEW_REQUIRED"}}];
